const proverbsData = [
  { id: 1, group: 1, kanji: "<ruby>愛<rt>あい</rt></ruby><ruby>想<rt>そ</rt></ruby>を<ruby>尽<rt>つ</rt></ruby>かす", kanjiPlain: "愛想を尽かす", meaning: "厭惡至極、感到嫌惡而不再搭理；徹底死心絕交。", story: "「愛想（あいそ）」指對人的好感或客氣親切態度。「尽かす（つかす）」是把……用盡之意。引申為對某人的言行徹底失望，好感耗盡，從此冷淡以對。", example: "<ruby>彼<rt>かれ</rt></ruby>の<ruby>不誠実<rt>ふせいじつ</rt></ruby>な<ruby>態度<rt>たいど</rt></ruby>に、すっかり<ruby>愛想<rt>あいそ</rt></ruby>を<ruby>尽<rt>つ</rt></ruby>かした。", exampleTrans: "對他那不誠實的態度徹底死心絕交了。" },
  { id: 2, group: 1, kanji: "<ruby>秋<rt>あき</rt></ruby>の<ruby>夕<rt>ゆう</rt></ruby><ruby>焼<rt>や</rt></ruby>け <ruby>鎌<rt>かま</rt></ruby>を<ruby>研<rt>と</rt></ruby>げ", kanjiPlain: "秋の夕焼け 鎌を研げ", meaning: "秋天出現晚霞，預示隔天是晴天，要磨好鐮刀準備收割。", story: "農業氣象的傳統觀測經驗諺語。秋季傍晚若天空出現紅霞，代表明日天氣放晴，農夫應趁早磨利鐮刀（鎌・かま），做好收割農作物的準備。", example: "「<ruby>秋<rt>あき</rt></ruby>の<ruby>夕焼<rt>ゆうや</rt></ruby>け<ruby>鎌<rt>かま</rt></ruby>を<ruby>研<rt>と</rt></ruby>げ」と<ruby>言<rt>い</rt></ruby>うから、<ruby>明日<rt>あした</rt></ruby>は<ruby>稲刈<rt>いねか</rt></ruby>りに<ruby>絶好<rt>ぜっこう</rt></ruby>の<ruby>日<rt>ひ</rt></ruby>和になるだろう。", exampleTrans: "正如俗話說「秋天傍晚見紅霞，磨利鐮刀備收割」，明天大概會是個非常適合收割稻穀的晴天吧。" },
  { id: 3, group: 1, kanji: "あごが<ruby>干<rt>ひ</rt></ruby><ruby>上<rt>あ</rt></ruby>がる", kanjiPlain: "あごが干上がる", meaning: "生活窮困失業，失去生活來源而吃不起飯。", story: "下巴（あご）用來咀嚼食物。若因貧困沒有食物吃，下巴便無用武之地，乾燥如乾涸（干あがる・ひあがる）一般。形容斷炊、無以為繼的窘境。", example: "<ruby>仕事<rt>しごと</rt></ruby>を<ruby>失<rt>うしな</rt></ruby>い、このままではあごが<ruby>干<rt>ひ</rt></ruby>あがってしまう。", exampleTrans: "失去了工作，再這樣下去就要三餐不繼、餓肚子了。" },
  { id: 4, group: 1, kanji: "あごで<ruby>使<rt>つか</rt></ruby>う", kanjiPlain: "あごで使う", meaning: "頤指氣使；傲慢地用下巴指使別人。", story: "不開口客氣說明，而是高高在上地微微揚起下巴來指揮人動作。形容以極度傲慢、瞧不起人的態度差遣部屬或他人。", example: "<ruby>人<rt>ひと</rt></ruby>をあごで<ruby>使<rt>つか</rt></ruby>うような<ruby>傲慢<rt>ごうまん</rt></ruby>な<ruby>態度<rt>たいど</rt></ruby>は<ruby>改<rt>あらた</rt></ruby>めるべきだ。", exampleTrans: "應當改掉那種頤指氣使、隨意差遣他人的傲慢態度。" },
  { id: 5, group: 1, kanji: "あごを<ruby>出<rt>だ</rt></ruby>す", kanjiPlain: "あごを出す", meaning: "疲憊不堪、精疲力竭、累得喘不過氣。", story: "人在極度疲倦奔走時，往往無法保持挺拔姿勢，下巴會無力地向前凸出大口喘氣。形容身體勞累疲憊到了極限。", example: "<ruby>山道<rt>やまみち</rt></ruby>を<ruby>五時間<rt>ごじかん</rt></ruby>も<ruby>歩<rt>ある</rt></ruby>いて、すっかりあごを<ruby>出<rt>だ</rt></ruby>してしまった。", exampleTrans: "連續走了五小時山路，整個人累得精疲力竭、氣喘吁吁。" },
  { id: 6, group: 1, kanji: "<ruby>朝<rt>あさ</rt></ruby><ruby>寝<rt>ね</rt></ruby><ruby>坊<rt>ぼう</rt></ruby>の<ruby>宵<rt>よい</rt></ruby>っぱり", kanjiPlain: "朝寝坊の宵っぱり", meaning: "晚睡晚起的人；夜貓子。", story: "「朝寝坊（あさねぼう）」指早晨賴床起不來；「宵っぱり（よいっぱり）」指初夜時分精神充沛不肯就寢。形容日夜顛倒的不規律作息。", example: "<ruby>夏休<rt>なつやす</rt></ruby>になると、つい<ruby>朝寝坊<rt>あさねぼう</rt></ruby>の<ruby>宵<rt>よい</rt></ruby>っぱりになってしまう。", exampleTrans: "一到暑假，就不知不覺變成了晚睡晚起的夜貓子生活。" },
  { id: 7, group: 1, kanji: "<ruby>足<rt>あし</rt></ruby>がつく", kanjiPlain: "足がつく", meaning: "露馬腳；露出線索而被查出行蹤或底細。", story: "原本多用於警匪搜查語境中，指犯人逃逸時留下了足跡、線索，讓警方順利追查到身份或行蹤。", example: "<ruby>防犯<rt>ぼうはん</rt></ruby>カメラの<ruby>映像<rt>えいぞう</rt></ruby>から<ruby>犯人<rt>はんにん</rt></ruby>の<ruby>足<rt>あし</rt></ruby>がついた。", exampleTrans: "透過防盜監視器的錄影畫面，查出了犯人的行蹤線索。" },
  { id: 8, group: 1, kanji: "<ruby>足<rt>あし</rt></ruby>が<ruby>鈍<rt>にぶ</rt></ruby>る", kanjiPlain: "足が鈍る", meaning: "腳步放慢；前進的勢頭或進度受阻減緩。", story: "「鈍る（にぶる）」為遲鈍、減緩。形容原本健步如飛的腳步因疲憊而慢下來，亦可引申為事情推展的進度放慢。", example: "<ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>り<ruby>始<rt>はじ</rt></ruby>めてから、<ruby>登山<rt>とざん</rt></ruby>の<ruby>足<rt>あし</rt></ruby>が<ruby>鈍<rt>にぶ</rt></ruby>った。", exampleTrans: "開始下雨之後，登山的步伐便漸漸放慢了。" },
  { id: 9, group: 1, kanji: "<ruby>足<rt>あし</rt></ruby>が<ruby>棒<rt>ぼう</rt></ruby>になる", kanjiPlain: "足が棒になる", meaning: "雙腿走得僵硬痠痛；兩腿發僵發直。", story: "走或站了非常久的時間之後，腿部肌肉發痠僵硬，變得像硬梆梆的木棒一樣難以自由彎曲屈伸。", example: "<ruby>一日中<rt>いちにちじゅう</rt></ruby><ruby>買<rt>か</rt></ruby>い<ruby>物<rt>もの</rt></ruby>に<ruby>付<rt>つ</rt></ruby>き<ruby>合<rt>あ</rt></ruby>わされて、<ruby>足<rt>あし</rt></ruby>が<ruby>棒<rt>ぼう</rt></ruby>になった。", exampleTrans: "陪著逛街採買了一整天，走得雙腳發僵、痠痛不已。" },
  { id: 10, group: 1, kanji: "<ruby>足<rt>あし</rt></ruby><ruby>元<rt>もと</rt></ruby>に<ruby>火<rt>ひ</rt></ruby>がつく", kanjiPlain: "足元に火がつく", meaning: "火燒眉毛；災難或危機已逼近眼前，萬分緊迫。", story: "火勢已經燒到腳邊（足元）。比喻危機、禍害或期限已經臨頭逼近，到了不得不立刻採取對策的萬分火急時刻。", example: "<ruby>締<rt>し</rt></ruby>め<ruby>切<rt>き</rt></ruby>り<ruby>前日<rt>ぜんじつ</rt></ruby>になってようやく<ruby>足元<rt>あしもと</rt></ruby>に<ruby>火<rt>ひ</rt></ruby>がついた。", exampleTrans: "到了截稿前一天，才終於感覺到火燒眉毛、萬分緊迫。" },
  { id: 11, group: 2, kanji: "<ruby>足<rt>あし</rt></ruby><ruby>元<rt>もと</rt></ruby>を<ruby>見<rt>み</rt></ruby>る", kanjiPlain: "足元を見る", meaning: "乘人之危；抓住對方的弱點或困境藉機敲竹槓。", story: "源於昔日驛站挑夫會觀察旅人腳步穿著與疲憊程度（看腳底）。若看準旅人疲憊急著投宿，便故意抬高過夜或搭乘費用。", example: "<ruby>足元<rt>あしもと</rt></ruby>を<ruby>見<rt>み</rt></ruby>られて、<ruby>高額<rt>こうがく</rt></ruby>な<ruby>修理費<rt>しゅうりひ</rt></ruby>を<ruby>請求<rt>せいきゅう</rt></ruby>された。", exampleTrans: "被對方抓住了急需的弱點趁機敲竹槓，索取了高昂的修理費用。" },
  { id: 12, group: 2, kanji: "<ruby>足<rt>あし</rt></ruby>を<ruby>洗<rt>あら</rt></ruby>う", kanjiPlain: "足を洗う", meaning: "洗心革面；金盆洗手，改過自新脫離惡行或不良圈子。", story: "佛教僧侶遠行托缽回到寺院時，洗清雙腳的泥濘塵埃以回到清淨佛門修行。引申為與昔日的犯罪或不正當行業徹底斷絕關係。", example: "<ruby>彼<rt>かれ</rt></ruby>は<ruby>悪<rt>わる</rt></ruby>い<ruby>仲間<rt>なかま</rt></ruby>と<ruby>縁<rt>えん</rt></ruby>を<ruby>切<rt>き</rt></ruby>り、すっかり<ruby>足<rt>あし</rt></ruby>を<ruby>洗<rt>あら</rt></ruby>った。", exampleTrans: "他與不良朋友斷絕往來，徹底金盆洗手、改過自新了。" },
  { id: 13, group: 2, kanji: "<ruby>足<rt>あし</rt></ruby>をのばす", kanjiPlain: "足をのばす", meaning: "順道前往更遠的地方；放鬆歇腳。", story: "本意為將縮起的腿伸直放鬆。引申為在原定行程結束後，順道將步伐擴展、走到稍微遠一點的地方遊歷參觀。", example: "<ruby>京都<rt>きょうと</rt></ruby>へ<ruby>行<rt>い</rt></ruby>ったついでに、<ruby>奈良<rt>なら</rt></ruby>まで<ruby>足<rt>あし</rt></ruby>をのばした。", exampleTrans: "去京都的時候，順道走遠了一點去奈良參觀。" },
  { id: 14, group: 2, kanji: "<ruby>足<rt>あし</rt></ruby>を<ruby>引<rt>ひ</rt></ruby>っ<ruby>張<rt>ぱ</rt></ruby>る", kanjiPlain: "足を引っ張る", meaning: "扯後腿；暗中妨礙或拖累團隊整體的成功進步。", story: "在後面拉住別人的腳步使其無法順利前進。比喻妨礙他人或拖累同儕、組織的進展與成果。", example: "<ruby>仲間<rt>なかま</rt></ruby>の<ruby>足<rt>あし</rt></ruby>を<ruby>引<rt>ひ</rt></ruby>っ<ruby>張<rt>ぱ</rt></ruby>らないよう、<ruby>自分<rt>じぶん</rt></ruby>の<ruby>役割<rt>やくわり</rt></ruby>をしっかり<ruby>果<rt>は</rt></ruby>たしたい。", exampleTrans: "希望能切實履行自己的職責，不拖累團隊、不扯同伴後腿。" },
  { id: 15, group: 2, kanji: "<ruby>明日<rt>あす</rt></ruby>は<ruby>明日<rt>あす</rt></ruby>の<ruby>風<rt>かぜ</rt></ruby>が<ruby>吹<rt>ふ</rt></ruby>く", kanjiPlain: "明日は明日の風が吹く", meaning: "明天有明天的風吹；船到橋頭自然直，不必為明日過度憂慮。", story: "無論今天遭逢何種挫折困難，明天的情況明天又會有新的變化。勸人放寬心胸，不要為尚未發生的事情過度自擾焦慮。", example: "<ruby>今悩<rt>いまなや</rt></ruby>んでも<ruby>仕方<rt>しかた</rt></ruby>がない。「<ruby>明日<rt>あした</rt></ruby>は<ruby>明日<rt>あした</rt></ruby>の<ruby>風<rt>かぜ</rt></ruby>が<ruby>吹<rt>ふ</rt></ruby>く」さ。", exampleTrans: "現在煩惱也沒有用。正如俗話說「船到橋頭自然直，明天自會有明天的路」。" },
  { id: 16, group: 2, kanji: "<ruby>頭<rt>あたま</rt></ruby><ruby>隠<rt>かく</rt></ruby>して<ruby>尻<rt>しり</rt></ruby><ruby>隠<rt>かく</rt></ruby>さず", kanjiPlain: "頭隠して尻隠さず", meaning: "藏頭露尾；欲蓋彌彰，自己以為隱瞞得很周全卻破綻百出。", story: "源自雉雞（キジ）被獵人追逐時，常把頭埋進草叢深處就自以為安全，卻把長長的尾部與屁股露在外面。形容缺漏明顯的拙劣掩飾。", example: "<ruby>言<rt>い</rt></ruby>い<ruby>訳<rt>わけ</rt></ruby>ばかりしているが、<ruby>頭<rt>あたま</rt></ruby><ruby>隠<rt>かく</rt></ruby>して<ruby>尻<rt>しり</rt></ruby><ruby>隠<rt>かく</rt></ruby>さずの<ruby>状態<rt>じょうたい</rt></ruby>だ。", exampleTrans: "雖然一直在找藉口狡辯，但根本是藏頭露尾、欲蓋彌彰。" },
  { id: 17, group: 2, kanji: "<ruby>頭<rt>あたま</rt></ruby>が<ruby>下<rt>さ</rt></ruby>がる", kanjiPlain: "頭が下がる", meaning: "佩服得五體投地；肅然起敬、令人由衷欽佩。", story: "因對方的品格、高尚行為或努力深感敬佩，而自然而然地低頭致敬行禮。形容令人打從心底欽敬讚嘆。", example: "<ruby>彼<rt>かれ</rt></ruby>の<ruby>長年<rt>ながねん</rt></ruby>にわたるボランティア<ruby>活動<rt>かつどう</rt></ruby>には<ruby>本当<rt>ほんとう</rt></ruby>に<ruby>頭<rt>あたま</rt></ruby>が<ruby>下<rt>さ</rt></ruby>がる。", exampleTrans: "他長年以來持續投入志工服務的精神，真令人由衷欽佩、肅然起敬。" },
  { id: 18, group: 2, kanji: "<ruby>頭<rt>あたま</rt></ruby>をもたげる", kanjiPlain: "頭をもたげる", meaning: "抬頭；隱藏的念頭、疑慮或勢力逐漸顯露抬頭。", story: "「もたげる」為抬起。原指頭部抬起，比喻心中的不安、懷疑或野心壓抑不住地冒了出來，亦可指勢力擴大崛起。", example: "<ruby>話<rt>はなし</rt></ruby>を<ruby>聞<rt>き</rt></ruby>くうちに、<ruby>心<rt>こころ</rt></ruby>の<ruby>中<rt>なか</rt></ruby>で<ruby>疑念<rt>ぎねん</rt></ruby>が<ruby>頭<rt>あたま</rt></ruby>をもたげてきた。", exampleTrans: "聽著聽著，心中逐漸冒出了懷疑的念頭。" },
  { id: 19, group: 2, kanji: "<ruby>後<rt>あと</rt></ruby><ruby>足<rt>あし</rt></ruby>で<ruby>砂<rt>すな</rt></ruby>をかける", kanjiPlain: "後足で砂をかける", meaning: "過河拆橋；受人恩惠卻在背後做出恩將仇報的醜事。", story: "狗、馬等動物離去時用後蹄把地面的砂石向後猛踢亂揚。比喻受到他人照顧或離開組織時，不思感謝反而做出危害對方的惡行。", example: "<ruby>世話<rt>せわ</rt></ruby>になった<ruby>恩人<rt>おんじん</rt></ruby>に<ruby>後足<rt>あとあし</rt></ruby>で<ruby>砂<rt>すな</rt></ruby>をかけるような<ruby>真似<rt>まね</rt></ruby>はするな。", exampleTrans: "絕不能做出過河拆橋、對照顧過自己的恩人恩將仇報的行為。" },
  { id: 20, group: 2, kanji: "<ruby>後<rt>あと</rt></ruby><ruby>味<rt>あじ</rt></ruby>が<ruby>悪<rt>わる</rt></ruby>い", kanjiPlain: "後味が悪い", meaning: "事後留下壞印象；令人心裡感到不舒服、疙瘩難消。", story: "原本指吃完食物後嘴裡留下的殘留餘味極差。引申為某件事結束之後，給人帶來內疚、不愉快或不舒服的後續感受。", example: "<ruby>喧嘩<rt>けんか</rt></ruby>をして<ruby>勝<rt>か</rt></ruby>ったものの、どうも<ruby>後味<rt>あとあじ</rt></ruby>が<ruby>悪<rt>わる</rt></ruby>い。", exampleTrans: "吵架雖然吵贏了，但事後心裡卻總覺得很不舒服、耿耿於懷。" },
  { id: 21, group: 3, kanji: "<ruby>後<rt>あと</rt></ruby>は<ruby>野<rt>の</rt></ruby>となれ<ruby>山<rt>やま</rt></ruby>となれ", kanjiPlain: "後は野となれ山となれ", meaning: "之後任憑洪水滔天；不管將來如何，眼前隨它去罷。", story: "只要眼前度過了難關，以後變成荒野或荒山都與我無關。形容極端不負責任、自暴自棄或豁出去的心態。", example: "<ruby>全財産<rt>ぜんざいさん</rt></ruby>をこのゲームに<ruby>投<rt>とう</rt></ruby>じよう。<ruby>後<rt>あと</rt></ruby>は<ruby>野<rt>の</rt></ruby>となれ<ruby>山<rt>やま</rt></ruby>となれだ。", exampleTrans: "把所有的家當都押在這個遊戲上吧！之後變成怎樣我都不管了！" },
  { id: 22, group: 3, kanji: "<ruby>穴<rt>あな</rt></ruby>があく", kanjiPlain: "穴があく", meaning: "出現漏洞；出現財務虧損或人事空缺。", story: "容器出現破洞，內部液體漏出。在社會語境中，常形容預算產生赤字虧損（穴埋め），或是崗位、席位產生了缺額留白。", example: "<ruby>急<rt>きゅう</rt></ruby>な<ruby>出費<rt>しゅっぴ</rt></ruby>が<ruby>重<rt>かさ</rt></ruby>なり、<ruby>今月<rt>こんげつ</rt></ruby>の<ruby>予算<rt>よさん</rt></ruby>に<ruby>大<rt>おお</rt></ruby>きな<ruby>穴<rt>あな</rt></ruby>があいた。", exampleTrans: "因為突如其來的支出接連增加，這個月的預算出現了很大的漏洞赤字。" },
  { id: 23, group: 3, kanji: "あぶはち<ruby>取<rt>と</rt></ruby>らず", kanjiPlain: "あぶはち取らず", meaning: "兩頭落空；貪多嚼不爛，想要兩樣結果一樣也沒得到。", story: "虻（あぶ・牛虻）與蜂（はち・蜜蜂）。想要兩者兼得同時捉取，結果一分心，連一隻也沒逮到。相當於中文的「兩頭落空」。", example: "<ruby>二兎<rt>にと</rt></ruby>を<ruby>追<rt>お</rt></ruby>うものは<ruby>一兎<rt>いっと</rt></ruby>をも<ruby>得<rt>え</rt></ruby>ず、あぶはち<ruby>取<rt>と</rt></ruby>らずの<ruby>結末<rt>けつまつ</rt></ruby>に<ruby>終<rt>お</rt></ruby>わった。", exampleTrans: "追兩隻兔子的人一隻也抓不到，落得了兩頭落空的下場。" },
  { id: 24, group: 3, kanji: "<ruby>雨<rt>あま</rt></ruby><ruby>垂<rt>だ</rt></ruby>れ<ruby>石<rt>いし</rt></ruby>をうがつ", kanjiPlain: "雨垂れ石をうがつ", meaning: "水滴石穿；只要堅持不懈，再微小的力量也能成大事。", story: "屋簷下滴落的雨水（雨垂れ）滴久了，也能在堅硬的岩石上穿孔（穿つ・うがつ）。比喻持之以恆必能成功突破難關。", example: "<ruby>毎日<rt>まいにち</rt></ruby>の<ruby>努力<rt>どりょく</rt></ruby>を<ruby>重<rt>かさ</rt></ruby>重ねれば、「<ruby>雨垂<rt>あまだ</rt></ruby>れ<ruby>石<rt>いし</rt></ruby>をうがつ」のたとえ<ruby>通<rt>どお</rt></ruby>り、きっと<ruby>夢<rt>ゆめ</rt></ruby>はかなう。", exampleTrans: "只要日積月累不斷努力，正如「水滴石穿」的俗諺所說，夢想一定能實現。" },
  { id: 25, group: 3, kanji: "<ruby>雨<rt>あめ</rt></ruby><ruby>降<rt>ふ</rt></ruby>って<ruby>地<rt>じ</rt></ruby><ruby>固<rt>かた</rt></ruby>まる", kanjiPlain: "雨降って地固まる", meaning: "不打不相識；風雨過後地基更穩固，經歷紛擾後關係更堅實。", story: "土地被雨水澆透之後，經由日曬水分蒸發，土質反而會比原來更加堅固緊密。形容經由衝突、挫折考驗後，彼此關係更加牢不可破。", example: "<ruby>本音<rt>ほんね</rt></ruby>でぶつかり<ruby>合<rt>あ</rt></ruby>ったことで、まさに「<ruby>雨<rt>あめ</rt></ruby><ruby>降<rt>ふ</rt></ruby>って<ruby>地<rt>じ</rt></ruby><ruby>固<rt>かた</rt></ruby>まる」となった。", exampleTrans: "雙方坦誠吵了一架之後，關係反而變得更加穩固親密了。" },
  { id: 26, group: 3, kanji: "ありの<ruby>穴<rt>あな</rt></ruby>から<ruby>堤<rt>つつみ</rt></ruby>もくずれる", kanjiPlain: "ありの穴から堤もくずれる", meaning: "千里之堤，潰於蟻穴；細微的疏忽可釀成巨大的災禍。", story: "出自《韓非子》。細小的螞蟻巢穴看似微不足道，但若任由水流滲透擴大，最後連高大堅固的河堤（堤・つつみ）也會崩塌潰敗。", example: "小さなミスを<ruby>放置<rt>ほうち</rt></ruby>してはいけない。ありの<ruby>穴<rt>あな</rt></ruby>から<ruby>堤<rt>つつみ</rt></ruby>もくずれるというからだ。", exampleTrans: "絕不能放任小錯誤不管，因為千里之堤往往潰於蟻穴。" },
  { id: 27, group: 3, kanji: "<ruby>案<rt>あん</rt></ruby>ずるより<ruby>産<rt>う</rt></ruby>むがやすい", kanjiPlain: "案ずるより産むがやすい", meaning: "想來煩惱，不如起而行；事情動手做起來往往比擔憂的簡單。", story: "孕婦臨產前總是百般焦慮恐懼痛苦，但真正分娩時過程往往比想像中順利平安。比喻事前憂心忡忡，實際上動手嘗試往往沒有那麼困難。", example: "<ruby>難<rt>むずか</rt></ruby>しそうに<ruby>思<rt>おも</rt></ruby>えたスピーチだが、「<ruby>案<rt>あん</rt></ruby>ずるより<ruby>産<rt>う</rt></ruby>むがやすい」でうまくできた。", exampleTrans: "演講看似很困難，但真正去做了之後發現事情往往比擔憂的簡單，順利完成了。" },
  { id: 28, group: 3, kanji: "<ruby>暗<rt>あん</rt></ruby><ruby>中<rt>ちゅう</rt></ruby><ruby>模<rt>も</rt></ruby><ruby>索<rt>さく</rt></ruby>", kanjiPlain: "暗中模索", meaning: "暗中摸索；在毫無頭緒與線索的摸索中尋求解決方法。", story: "如同在黑暗摸不著光線之處四處摸索探尋。形容在情況完全不明朗、毫無指南借鏡的情況下一步步試驗尋找方向。", example: "<ruby>新<rt>あたら</rt></ruby>しい事業の立ち上げは、まさに<ruby>暗中<rt>あんちゅう</rt></ruby><ruby>模索<rt>もさく</rt></ruby>の<ruby>連続<rt>れんぞく</rt></ruby>だった。", exampleTrans: "開創新事業的過程，完全是在沒有前例的情況下不斷暗中摸索。" },
  { id: 29, group: 3, kanji: "<ruby>家<rt>いえ</rt></ruby>をたたむ", kanjiPlain: "家をたたむ", meaning: "收起家業；清理變賣家產以遷居或關閉家門。", story: "「たたむ」為折疊收納、結束營業之意。把一個家庭的所有家當收拾處理，不再於該地維持家庭運作。", example: "<ruby>両親<rt>りょうしん</rt></ruby>は<ruby>田舎<rt>いなか</rt></ruby>の<ruby>家<rt>いえ</rt></ruby>をたたみ、<ruby>私<rt>わたし</rt></ruby>たちの近くへ引っ越してきた。", exampleTrans: "父母把鄉下的老家收拾變賣，搬到了我們家附近同住。" },
  { id: 30, group: 3, kanji: "<ruby>息<rt>いき</rt></ruby>が<ruby>合<rt>あ</rt></ruby>う", kanjiPlain: "息が合う", meaning: "步調一致、配合默契；合拍、心靈相通。", story: "形容兩個人呼吸起伏的節奏完全一致。引申為共同工作或表演時默契極佳，無需言語提醒就能完美配合。", example: "<ruby>長年<rt>ながねん</rt></ruby>ペアを組んでいる二人は、実に<ruby>息<rt>いき</rt></ruby>が<ruby>合<rt>あ</rt></ruby>っている。", exampleTrans: "搭檔多年的兩個人，默契真是無懈可擊、配合得天衣無縫。" },
  { id: 31, group: 4, kanji: "<ruby>息<rt>いき</rt></ruby>の<ruby>根<rt>ね</rt></ruby>を<ruby>止<rt>と</rt></ruby>める", kanjiPlain: "息の根を止める", meaning: "置於死地；徹底擊潰、使對方毫無翻身喘息的餘地。", story: "「息の根」指呼吸的根本或氣管。勒住呼吸使其窒息，比喻徹底消滅對手或給予致命一擊，使其徹底垮台。", example: "<ruby>徹底的<rt>てっていてき</rt></ruby>な<ruby>反論<rt>はんろん</rt></ruby>で、<ruby>相手<rt>あいて</rt></ruby>の<ruby>息<rt>いき</rt></ruby>の<ruby>根<rt>ね</rt></ruby>を<ruby>止<rt>と</rt></ruby>めた。", exampleTrans: "透過徹底且毫無破綻的反駁，徹底擊潰了對手。" },
  { id: 32, group: 4, kanji: "<ruby>息<rt>いき</rt></ruby>をこらす", kanjiPlain: "息をこらす", meaning: "屏氣凝神；專心致志、緊張得不敢出聲喘氣。", story: "「こらす（凝らす）」是集中、凝集之意。形容在極度緊張、專注或期待的關鍵時刻，自覺地屏住呼吸。", example: "<ruby>観客<rt>かんきゃく</rt></ruby>は<ruby>息<rt>いき</rt></ruby>をこらして、<ruby>劇的<rt>げきてき</rt></ruby>なラストシーンを<ruby>見守<rt>みまも</rt></ruby>った。", exampleTrans: "觀眾們屏氣凝神，聚精會神地注視著戲劇性的最後一幕。" },
  { id: 33, group: 4, kanji: "<ruby>息<rt>いき</rt></ruby>をはずませる", kanjiPlain: "息をはずませる", meaning: "上氣不接下氣；呼吸急促、氣喘吁吁。", story: "「はずむ（弾む）」指彈跳、跳動。形容因劇烈奔跑運動，或是激動興奮而導致心跳加速、呼吸頻繁急促起伏。", example: "<ruby>階段<rt>かいだん</rt></ruby>を<ruby>一気<rt>いっき</rt></ruby>に<ruby>駆<rt>か</rt></ruby>け<ruby>上<rt>あ</rt></ruby>がり、<ruby>息<rt>いき</rt></ruby>をはずませていた。", exampleTrans: "一口氣衝上了樓梯，累得上氣不接下氣。" },
  { id: 34, group: 4, kanji: "<ruby>息<rt>いき</rt></ruby>を<ruby>引<rt>ひ</rt></ruby>き<ruby>取<rt>と</rt></ruby>る", kanjiPlain: "息を引き取る", meaning: "斷氣；咽氣、與世長辭。", story: "指停止最後一口呼吸。為日語中描述生命終結、安詳離世時常用的委婉敬意表現。", example: "<ruby>祖父<rt>そふ</rt></ruby>は<ruby>家族<rt>かぞく</rt></ruby>に<ruby>見守<rt>みまも</rt></ruby>られながら、<ruby>静<rt>しず</rt></ruby>かに<ruby>息<rt>いき</rt></ruby>を<ruby>引<rt>ひ</rt></ruby>き<ruby>取<rt>と</rt></ruby>った。", exampleTrans: "祖父在全家人的守護與陪伴下，安詳地與世長辭了。" },
  { id: 35, group: 4, kanji: "<ruby>息<rt>いき</rt></ruby>をふき<ruby>返<rt>かえ</rt></ruby>す", kanjiPlain: "息をふき返す", meaning: "甦醒復生；起死回生、重獲生機活力。", story: "原本看似停止呼吸或瀕死的人重新恢復氣息。引申指衰退瀕危的組織、低迷的經濟或失去活力的事物再度重現生機。", example: "<ruby>水<rt>みず</rt></ruby>をあげたら、<ruby>枯<rt>か</rt></ruby>れかけていた<ruby>花<rt>はな</rt></ruby>が<ruby>息<rt>いき</rt></ruby>をふき<ruby>返<rt>かえ</rt></ruby>した。", exampleTrans: "澆了水之後，原本快要枯萎的花朵又重新恢復了生機。" },
  { id: 36, group: 4, kanji: "<ruby>石<rt>いし</rt></ruby>にかじりついても", kanjiPlain: "石にかじりついても", meaning: "哪怕咬碎石頭也要堅持；竭盡全力、不惜任何代價堅決達成。", story: "「かじりつく」意為咬住不放。比喻即使面臨咬石頭般的極大苦痛與艱困，也抱持不退縮、堅持奮鬥到底的堅定意志。", example: "<ruby>石<rt>いし</rt></ruby>にかじりついても、このプロジェクトを<ruby>成功<rt>せいこう</rt></ruby>させてみせる。", exampleTrans: "哪怕再艱難辛苦，我也一定要讓這個專案獲得成功。" },
  { id: 37, group: 4, kanji: "<ruby>石<rt>いし</rt></ruby>の<ruby>上<rt>うえ</rt></ruby>にも<ruby>三<rt>さん</rt></ruby><ruby>年<rt>ねん</rt></ruby>", kanjiPlain: "石の上にも三年", meaning: "鐵杵磨成針；再冷硬的石頭坐上三年也會變暖，比喻持之以恆終能成功。", story: "源自禪宗達摩祖師面壁坐禪等修行傳說。冰冷頑固的石頭只要坐久了也會變熱，勉勵人凡事只要有耐心耐力，必定能迎來收穫。", example: "「<ruby>石<rt>いし</rt></ruby>の<ruby>上<rt>うえ</rt></ruby>にも<ruby>三年<rt>さんねん</rt></ruby>」というように、つらい<ruby>下積<rt>したづ</rt></ruby>みを<ruby>耐<rt>た</rt></ruby>えて<ruby>技術<rt>ぎじゅつ</rt></ruby>を<ruby>磨<rt>みが</rt></ruby>いた。", exampleTrans: "正如俗話說「功到自然成」，耐住了辛苦的磨練期，終於磨練出一身好技術。" },
  { id: 38, group: 4, kanji: "<ruby>石<rt>いし</rt></ruby><ruby>橋<rt>ばし</rt></ruby>をたたいて<ruby>渡<rt>わた</rt></ruby>る", kanjiPlain: "石橋をたたいて渡る", meaning: "摸著石頭過河；小心謹慎至極、行事再三確認以防萬一。", story: "原本就堅固無比的石橋，在過橋前還要先拿拐杖敲一敲確認牢固。形容處事格外審慎細心，完全不冒任何風險。", example: "<ruby>彼<rt>かれ</rt></ruby>は<ruby>石橋<rt>いしばし</rt></ruby>をたたいて<ruby>渡<rt>わた</rt></ruby>るような<ruby>慎重<rt>しんちょう</rt></ruby>な<ruby>性格<rt>せいかく</rt></ruby>で、ミスをほとんどしない。", exampleTrans: "他的性格極為謹慎小心，行事再三確認，幾乎從來不出差錯。" },
  { id: 39, group: 4, kanji: "<ruby>意地<rt>いじ</rt></ruby>を<ruby>張<rt>は</rt></ruby>る", kanjiPlain: "意地を張る", meaning: "耍固執、逞強；明知不妥卻不肯服輸讓步。", story: "「意地」指脾氣或要強的自尊心。形容為了不服輸或面子問題，明知自己有錯或不智，仍執拗地堅持己見不肯低頭。", example: "<ruby>意地<rt>いじ</rt></ruby>を<ruby>張<rt>は</rt></ruby>らずに、<ruby>素直<rt>すなお</rt></ruby>に<ruby>謝<rt>あやま</rt></ruby>ったほうがいいよ。", exampleTrans: "別再死撐固執了，坦率地向對方道個歉比較好喔。" },
  { id: 40, group: 4, kanji: "<ruby>急<rt>いそ</rt></ruby>がば<ruby>回<rt>まわ</rt></ruby>れ", kanjiPlain: "急がば回れ", meaning: "欲速則不達；越是著急時，走安全平穩的遠路反而更快到達。", story: "源自室町時代宗長連歌師的和歌。原本穿越琵琶湖的水路看似捷徑卻常遇狂風暴雨翻船，不如繞岸邊陸路雖遠卻能安全抵達。", example: "<ruby>近道<rt>ちかみち</rt></ruby>をして<ruby>道<rt>みち</rt></ruby>に<ruby>迷<rt>まよ</rt></ruby>うより、「<ruby>急<rt>いそ</rt></ruby>がば<ruby>回<rt>まわ</rt></ruby>れ」で<ruby>大通<rt>おおどお</rt></ruby>りを<ruby>行<rt>い</rt></ruby>こう。", exampleTrans: "與其抄捷徑反而迷路，不如「欲速則不達」，走大馬路反而更穩當。" },
  { id: 41, group: 5, kanji: "<ruby>一<rt>いち</rt></ruby>か<ruby>八<rt>ばち</rt></ruby>か", kanjiPlain: "一か八か", meaning: "孤注一擲；拼一把、聽天由命看運氣成敗。", story: "源於傳統骰子賭博博弈。漢字「一」上面為一劃，而「八」則是「罰（ばち）」字偏旁的頂端筆畫。比喻在沒有勝算把握時拼命一搏。", example: "<ruby>合格<rt>ごうかく</rt></ruby>するかどうか分からないが、<ruby>一<rt>いち</rt></ruby>か<ruby>八<rt>ばち</rt></ruby>か<ruby>挑戦<rt>ちょうせん</rt></ruby>してみる。", exampleTrans: "雖然不知道能不能考上，但還是決定孤注一擲試著挑戰看看。" },
  { id: 42, group: 5, kanji: "<ruby>一<rt>いち</rt></ruby>から<ruby>十<rt>じゅう</rt></ruby>まで", kanjiPlain: "一から十まで", meaning: "徹頭徹尾、事無巨細；從頭到尾無一遺漏。", story: "從數字 1 到 10 全部涵蓋。形容說話或交代事情時毫無保留、全面鉅細靡遺地交代或照單全收。", example: "<ruby>新入社員<rt>しんにゅうしゃいん</rt></ruby>に、<ruby>仕事<rt>しごと</rt></ruby>の<ruby>手順<rt>てじゅん</rt></ruby>を<ruby>一<rt>いち</rt></ruby>から<ruby>十<rt>じゅう</rt></ruby>まで<ruby>丁寧<rt>ていねい</rt></ruby>に<ruby>教<rt>おし</rt></ruby>えた。", exampleTrans: "從頭到尾、事無巨細地向新進員工細心指導工作流程。" },
  { id: 43, group: 5, kanji: "<ruby>一<rt>いち</rt></ruby><ruby>事<rt>じ</rt></ruby>が<ruby>万事<rt>ばんじ</rt></ruby>", kanjiPlain: "一事が万事", meaning: "由小見大；一葉知秋，從一件事的端倪就能推知全貌。", story: "看到某個單一表現或細節，就能推斷該人平常其他事情的大體作風。多用於批評人細節不佳、處事粗心等負面脈絡。", example: "<ruby>彼<rt>かれ</rt></ruby>の<ruby>遅刻<rt>ちこく</rt></ruby>は<ruby>今日<rt>きょう</rt></ruby>に<ruby>限<rt>かぎ</rt></ruby>ったことではない。<ruby>一事<rt>いちじ</rt></ruby>が<ruby>万事<rt>ばんじ</rt></ruby>、いつもだらしない。", exampleTrans: "他的遲到不是今天才發生的。由小見大，他平時做什麼事都是這樣散漫隨便。" },
  { id: 44, group: 5, kanji: "<ruby>一<rt>いち</rt></ruby><ruby>日<rt>じつ</rt></ruby><ruby>千<rt>せん</rt></ruby><ruby>秋<rt>しゅう</rt></ruby>", kanjiPlain: "一日千秋", meaning: "一日三秋；度日如年，盼望思念之情極為迫切。", story: "出自《詩經》。一天過得像一千個秋天那麼漫長。形容思慕牽掛之情極深，或迫切期盼某個日子到來的急迫心境。", example: "<ruby>恋人<rt>こいびと</rt></ruby>からの<ruby>返事<rt>へんじ</rt></ruby>を、<ruby>一日千秋<rt>いちじつせんしゅう</rt></ruby>の<ruby>思<rt>おも</rt></ruby>いで<ruby>待<rt>ま</rt></ruby>ち<ruby>焦<rt>こ</rt></ruby>がれる。", exampleTrans: "以度日如年般迫切的心情，苦苦期盼著戀人的回覆。" },
  { id: 45, group: 5, kanji: "<ruby>一<rt>いち</rt></ruby><ruby>難<rt>なん</rt></ruby><ruby>去<rt>さ</rt></ruby>ってまた<ruby>一<rt>いち</rt></ruby><ruby>難<rt>なん</rt></ruby>", kanjiPlain: "一難去ってまた一難", meaning: "一波未平，一波又起；剛擺脫一個困難，新的災厄又接踵而來。", story: "度過了一個艱難關頭（一難），馬上又有新的災禍降臨。形容接連不斷的困境與考驗。", example: "<ruby>風邪<rt>かぜ</rt></ruby>が<ruby>治<rt>なお</rt></ruby>ったと<ruby>思<rt>おも</rt></ruby>ったら<ruby>今度<rt>こんど</rt></ruby>は<ruby>腰<rt>こし</rt></ruby>を<ruby>痛<rt>いた</rt></ruby>め、まさに<ruby>一難<rt>いちなん</rt></ruby><ruby>去<rt>さ</rt></ruby>ってまた<ruby>一難<rt>いちなん</rt></ruby>だ。", exampleTrans: "才剛覺得感冒痊癒了，這次卻又扭傷了腰，真是一波未平一波又起。" },
  { id: 46, group: 5, kanji: "<ruby>一<rt>いち</rt></ruby><ruby>年<rt>ねん</rt></ruby>の<ruby>計<rt>けい</rt></ruby>は<ruby>元<rt>がん</rt></ruby><ruby>旦<rt>たん</rt></ruby>にあり", kanjiPlain: "一年の計は元旦にあり", meaning: "一年之計在於春；萬事貴在早做打算、從起點便立下切實計畫。", story: "出自明代馮應京《月令廣義》。一年的規劃應當在年初第一天（元旦）確立好。強調凡事預則立，及早規劃至關重要。", example: "「<ruby>一年<rt>いちねん</rt></ruby>の<ruby>計<rt>けい</rt></ruby>は<ruby>元旦<rt>がんたん</rt></ruby>にあり」だから、お<ruby>正月<rt>しょうがつ</rt></ruby>に<ruby>今年<rt>ことし</rt></ruby>の<ruby>目標<rt>もくひょう</rt></ruby>をノートに<ruby>書<rt>か</rt></ruby>き<ruby>出<rt>だ</rt></ruby>した。", exampleTrans: "正所謂「一年之計在於春」，所以在新年第一天就把今年的目標寫在筆記本上。" },
  { id: 47, group: 5, kanji: "<ruby>一<rt>いち</rt></ruby><ruby>富<rt>ふ</rt></ruby><ruby>士<rt>じ</rt></ruby><ruby>二<rt>に</rt></ruby>たか<ruby>三<rt>さん</rt></ruby>なすび", kanjiPlain: "一富士二たか三なすび", meaning: "初夢吉兆；日本傳統新年吉夢順序（一富士山、二老鷹、三茄子）。", story: "江戶時代起流傳的新年吉夢順位。富士山象徵平安長壽；老鷹（鷹・たか）高飛爪健象徵高昇與力量；茄子（茄子・なすび）與「成す（達成成就）」諧音。", example: "<ruby>初夢<rt>はつゆめ</rt></ruby>で<ruby>富士山<rt>ふじさん</rt></ruby>を<ruby>見<rt>み</rt></ruby>た。「<ruby>一富士<rt>いちふじ</rt></ruby><ruby>二鷹<rt>にたか</rt></ruby><ruby>三茄子<rt>さんなすび</rt></ruby>」で、<ruby>縁起<rt>えんぎ</rt></ruby>がとてもいい。", exampleTrans: "新年第一場夢夢見了富士山。這正是「一富士二鷹三茄子」，象徵非常吉利好運。" },
  { id: 48, group: 5, kanji: "<ruby>一<rt>いち</rt></ruby><ruby>網<rt>もう</rt></ruby><ruby>打<rt>だ</rt></ruby><ruby>尽<rt>じん</rt></ruby>", kanjiPlain: "一網打尽", meaning: "一網打盡；撒下一張魚網把魚全數捕獲，比喻將罪犯全夥一舉捉拿。", story: "出自宋代魏泰《東軒筆錄》。原本指一次收網捕光所有游魚，現多用於警察、司法機關將犯罪集團徹底連根拔起破獲。", example: "<ruby>警察<rt>けいさつ</rt></ruby>の<ruby>捜査<rt>そうさ</rt></ruby>により、<ruby>特殊詐欺<rt>とくしゅさぎ</rt></ruby>グループが<ruby>一網打尽<rt>いちもうだじん</rt></ruby>にされた。", exampleTrans: "經過警方的縝密調查，特殊電信詐騙集團被一網打盡了。" },
  { id: 49, group: 5, kanji: "<ruby>一<rt>いち</rt></ruby><ruby>目<rt>もく</rt></ruby>おく", kanjiPlain: "一目おく", meaning: "甘拜下風、退避三舍；承認對手實力高強而給予敬重禮讓。", story: "圍棋術語。棋力較弱的一方在開局前先在棋盤上下第一顆子（一目置く）作為讓子。引申為由衷敬佩並認可對方的卓越能力。", example: "<ruby>彼<rt>かれ</rt></ruby>のプログラミングの<ruby>腕前<rt>うでまえ</rt></ruby>には、ベテラン社員も<ruby>一目<rt>いちもく</rt></ruby>おいている。", exampleTrans: "談到他的程式編寫功力，連資深老員工也對他敬佩三分、自嘆不如。" },
  { id: 50, group: 5, kanji: "<ruby>一<rt>いち</rt></ruby>れんたく<ruby>生<rt>しょう</rt></ruby>", kanjiPlain: "一れんたく生", meaning: "休戚與共、生死同舟；無論好壞命運皆緊密綁在一起。", story: "佛教用語。善行者死後共同往生西方極樂淨土，轉生在同一朵蓮花托座上。現常用於比喻夥伴或同仁命運相連，同生共死。", example: "<ruby>我<rt>われ</rt></ruby>われは<ruby>同<rt>おな</rt></ruby>じチームとして<ruby>一蓮托生<rt>いちれんたくしょう</rt></ruby>の<ruby>運命<rt>うんめい</rt></ruby>にある。", exampleTrans: "我們身為同一個團隊，彼此命運相連、休戚與共。" },
  { id: 51, group: 6, kanji: "<ruby>一<rt>いっ</rt></ruby><ruby>家<rt>か</rt></ruby>を<ruby>成<rt>な</rt></ruby>す", kanjiPlain: "一家を成す", meaning: "自成一家；在學術、藝術或專業領域獨創體系、享有卓越地位。", story: "除了成家立業之意，在成語修辭中常指學者或藝術家具備獨特創見與風格，創立了受人公認的一派體系。", example: "<ruby>彼<rt>かれ</rt></ruby>は<ruby>独自<rt>どくじ</rt></ruby>の<ruby>理論<rt>りろん</rt></ruby>を<ruby>確立<rt>かくりつ</rt></ruby>し、<ruby>建築界<rt>けんちくかい</rt></ruby>で<ruby>一家<rt>いっか</rt></ruby>を<ruby>成<rt>な</rt></ruby>した。", exampleTrans: "他確立了自己獨特的設計理論，在建築界自成一家、享有崇高地位。" },
  { id: 52, group: 6, kanji: "<ruby>一<rt>いっ</rt></ruby><ruby>挙<rt>きょ</rt></ruby><ruby>両<rt>りょう</rt></ruby><ruby>得<rt>とく</rt></ruby>", kanjiPlain: "一挙両得", meaning: "一舉兩得；付出一份心力或做一個舉動，同時收穫兩重好處。", story: "出自《晉書·束皙傳》。一個舉動獲得雙重收穫。在日語日常對話中亦常與「一石二鳥（いっせきにちょう）」替換使用。", example: "<ruby>自転車<rt>じてんしゃ</rt></ruby><ruby>通勤<rt>つうきん</rt></ruby>は<ruby>運動<rt>うんどう</rt></ruby>にもなり<ruby>交通費<rt>こうつうひ</rt></ruby>も<ruby>浮<rt>う</rt></ruby>くので、まさに<ruby>一挙両得<rt>いっきょりょうとく</rt></ruby>だ。", exampleTrans: "騎自行車上班既能鍛鍊身體又能省下交通費，真是一舉兩得。" },
  { id: 53, group: 6, kanji: "<ruby>一<rt>いっ</rt></ruby><ruby>刻<rt>こく</rt></ruby><ruby>千<rt>せん</rt></ruby><ruby>金<rt>きん</rt></ruby>", kanjiPlain: "一刻千金", meaning: "一刻千金；光陰寶貴，極為短暫的時間價值千金。", story: "出自蘇軾詩作《春夜》：「春宵一刻值千金，花有清香月有陰。」形容極其寶貴愉悅的美好時光，每分每秒都值得好好珍惜。", example: "<ruby>試験<rt>しけん</rt></ruby><ruby>直前<rt>ちょくぜん</rt></ruby>の<ruby>今<rt>いま</rt></ruby>は、まさに<ruby>一刻千金<rt>いっこくせんきん</rt></ruby>の<ruby>貴重<rt>きちょう</rt></ruby>な<ruby>時間<rt>じかん</rt></ruby>だ。", exampleTrans: "考試迫在眉睫的現在，正是分秒必爭、一刻千金的寶貴時光。" },
  { id: 54, group: 6, kanji: "<ruby>一<rt>いっ</rt></ruby><ruby>矢<rt>し</rt></ruby>を<ruby>報<rt>むく</rt></ruby>いる", kanjiPlain: "一矢を報いる", meaning: "奮力反擊；在處於絕對劣勢下，仍竭力給予對方回擊或挽回顏面。", story: "戰場上遭到敵軍萬箭齊發猛烈圍攻時，仍然在最後回射出一支箭。「報いる」為回敬。比喻雖敗猶榮的頑強抵抗。", example: "<ruby>試合<rt>しあい</rt></ruby>には<ruby>負<rt>ま</rt></ruby>けたが、<ruby>強豪<rt>きょうごう</rt></ruby>相手に<ruby>一矢<rt>いっし</rt></ruby>を<ruby>報<rt>むく</rt></ruby>いるゴールを決めた。", exampleTrans: "比賽雖然輸了，但面對強勁對手仍攻入一球成功予以反擊。" },
  { id: 55, group: 6, kanji: "<ruby>一<rt>いっ</rt></ruby><ruby>寸<rt>すん</rt></ruby><ruby>先<rt>さき</rt></ruby>はやみ", kanjiPlain: "一寸先はやみ", meaning: "世事難料；往前一步便是未知的黑暗，未來吉凶禍福難以預測。", story: "「一寸（約 3 公分）」比喻極短的距離或短暫的未來。就算只邁出一小步也是伸手不見五指的黑暗。感嘆命運無常、隨時可能生變。", example: "「<ruby>一寸先<rt>いっすんさき</rt></ruby>は<ruby>闇<rt>やみ</rt></ruby>」の<ruby>世<rt>よ</rt></ruby>の<ruby>中<rt>なか</rt></ruby>だからこそ、日頃の備えが<ruby>大切<rt>たいせつ</rt></ruby>だ。", exampleTrans: "正因為世事難料、未來難測，平時的防範與準備才格外重要。" },
  { id: 56, group: 6, kanji: "<ruby>一<rt>いっ</rt></ruby><ruby>寸<rt>すん</rt></ruby>の<ruby>虫<rt>むし</rt></ruby>にも<ruby>五<rt>ご</rt></ruby><ruby>分<rt>ぶん</rt></ruby>の<ruby>魂<rt>たましい</rt></ruby>", kanjiPlain: "一寸の虫にも五分の魂", meaning: "麻雀雖小，五臟俱全；哪怕再微小弱小的人物，也有不可輕侮的骨氣。", story: "即使只有一寸長的小蟲子，也有半寸（五分）的靈魂與尊嚴。告誡強者萬萬不可仗勢欺凌藐視弱小者。", example: "「<ruby>一寸<rt>いっすん</rt></ruby>の<ruby>虫<rt>むし</rt></ruby>にも<ruby>五分<rt>ごぶ</rt></ruby>の<ruby>魂<rt>たましい</rt></ruby>」だ、<ruby>新入生<rt>しんにゅうせい</rt></ruby>だからといってバカにしてはいけない。", exampleTrans: "「弱小者也有其骨氣與尊嚴」，千萬不能只因為對方是新生就看扁人家。" },
 { id: 57, group: 6, kanji: "<ruby>一<rt>いっ</rt></ruby><ruby>朝<rt>ちょう</rt></ruby><ruby>一<rt>いっ</rt></ruby><ruby>夕<rt>せき</rt></ruby>", kanjiPlain: "一朝一夕", meaning: "一朝一夕；極短暫的時間，通常用於「非一朝一夕之功」的否定句式。", story: "出自《易經·坤卦》。早晨到傍晚的時間。通常搭配否定形式「〜ではできない」，表示深厚學養或成果並非短時間內能促成。", example: "<ruby>外国語<rt>がいこくご</rt></ruby>の<ruby>習得<rt>しゅうとく</rt></ruby>は、「<ruby>一朝一夕<rt>いっちょういっせき</rt></ruby>」にはいかない。", exampleTrans: "外語能力的養成絕非一朝一夕就能輕鬆促成。" },
  { id: 58, group: 6, kanji: "<ruby>命<rt>いのち</rt></ruby>あっての<ruby>物種<rt>ものだね</rt></ruby>", kanjiPlain: "命あっての物種", meaning: "留得青山在，不怕沒柴燒；只要保住性命，一切皆有重新來過的希望。", story: "「物種（ものだね）」指長出萬物的種子或根基。生命是成就一切事業與幸福的基礎，如果性命丟了，再多的財富名利都毫無意義。", example: "<ruby>無理<rt>むり</rt></ruby>をして体を壊しては元も子もない。「<ruby>命<rt>いのち</rt></ruby>あっての<ruby>物種<rt>ものだね</rt></ruby>」だから<ruby>休養<rt>きゅうよう</rt></ruby>しよう。", exampleTrans: "勉強硬撐把身体搞垮了就什麼都沒了。「留得青山在不怕沒柴燒」，先好好休息吧。" },
  { id: 59, group: 6, kanji: "<ruby>芋<rt>いも</rt></ruby>を<ruby>洗<rt>あら</rt></ruby>うよう", kanjiPlain: "芋を洗うよう", meaning: "人山人海；像大桶洗地瓜般擁擠不堪、摩肩接踵。", story: "古時洗芋頭（里芋）時，會把大量芋頭倒在木桶中用木棒攪動，芋頭互相碰撞摩擦去皮。形容公共場所人群擁擠磨蹭的盛況。", example: "<ruby>夏休<rt>なつやす</rt></ruby>みのプールは、<ruby>芋<rt>いも</rt></ruby>を<ruby>洗<rt>あら</rt></ruby>うような<ruby>大混雑<rt>だいこんざつ</rt></ruby>だった。", exampleTrans: "暑假期間的游泳池擠得水泄不通，簡直像在木桶裡洗地瓜一樣人擠人。" },
  { id: 60, group: 6, kanji: "<ruby>色<rt>いろ</rt></ruby>をつける", kanjiPlain: "色をつける", meaning: "給點甜頭、額外優惠；酌情給予寬容或折扣讓步。", story: "原本是在樸素的布料上增添鮮豔色彩使其更有價值。在商業買賣或交涉中，引申指賣方額外給予折價讓步或多送贈品。", example: "<ruby>少<rt>すこ</rt></ruby>し<ruby>色<rt>いろ</rt></ruby>をつけてくれたら、この<ruby>商品<rt>しょうひん</rt></ruby>をまとめ<ruby>買<rt>が</rt></ruby>いしますよ。", exampleTrans: "如果老闆願意再給一點折扣甜頭，我就把這些商品整批買下來。" },
  { id: 61, group: 7, kanji: "いわしの<ruby>頭<rt>あたま</rt></ruby>も<ruby>信心<rt>しんじん</rt></ruby>から", kanjiPlain: "いわしの頭も信心から", meaning: "精誠所至，金石為開；信則靈，只要虔誠相信，微不足道的東西也會產生不可思議的神力。", story: "日本民間在節分（せつぶん）時有在門口插沙丁魚頭和柊樹枝以驅邪的習俗。即使是腥臭微賤的沙丁魚頭，只要誠心敬拜也會成為神聖之物。形容信仰或執念力量的強大。", example: "「いわしの<ruby>頭<rt>あたま</rt></ruby>も<ruby>信心<rt>しんじん</rt></ruby>から」で、お<ruby>守<rt>まも</rt></ruby>りを<ruby>持<rt>も</rt></ruby>っているだけで<ruby>不思議<rt>ふしぎ</rt></ruby>と<ruby>安心<rt>あんしん</rt></ruby>できる。", exampleTrans: "正如俗話說「信則靈」，光是隨身攜帶著護身符，心裡就會感到不可思議的安心。" },
  { id: 62, group: 7, kanji: "<ruby>言<rt>い</rt></ruby>わぬが<ruby>花<rt>はな</rt></ruby>", kanjiPlain: "言わぬが花", meaning: "不說為妙；少說為佳，含蓄不言反而更具美感或避免紛爭。", story: "源自世阿彌《風姿花傳》中的能樂美學「秘すれば花（隱藏不露方為精華）」。很多事情若全挑明講開反而失去美感或傷人感情，適度保留不說反而是最好的處世智慧。", example: "そのことについてこれ<ruby>以上<rt>いじょう</rt></ruby>つっこむのは「<ruby>言<rt>い</rt></ruby>わぬが<ruby>花<rt>はな</rt></ruby>」だよ。", exampleTrans: "關於那件事，不再繼續追問下去才是明智的選擇、不說為妙喔。" },
  { id: 63, group: 7, kanji: "いんぎん<ruby>無礼<rt>ぶれい</rt></ruby>", kanjiPlain: "いんぎん無礼", meaning: "客氣過頭反而失禮；表面極度謙恭，骨子裡卻傲慢無禮。", story: "「慇懃（いんぎん）」原本指禮貌非常周到、慇勤。但若客氣得太過誇張矯情，反而會給人疏離、諷刺或高高在上的嘲弄感，變成一種無禮。", example: "<ruby>丁寧<rt>ていねい</rt></ruby>すぎる<ruby>敬語<rt>けいご</rt></ruby>を連発され、かえっていんぎん<ruby>無礼<rt>ぶれい</rt></ruby>に<ruby>感<rt>かん</rt></ruby>じた。", exampleTrans: "對方連珠炮似地使用過度客氣的敬語，反而讓人覺得表面謙恭、骨子裡極不尊重。" },
  { id: 64, group: 7, kanji: "う<ruby>合<rt>ごう</rt></ruby>の<ruby>衆<rt>しゅう</rt></ruby>", kanjiPlain: "う合の衆", meaning: "烏合之眾；毫無組織紀律、臨時湊在一起的烏合群體。", story: "出自《後漢書·耿弇傳》。像烏鴉（烏・う）群聚一般，雖然數量眾多，但彼此缺乏統一意志、紀律與統御，一遇衝擊便作鳥獸散。", example: "いくら人数が多くても、統率が取れていなければう<ruby>合<rt>ごう</rt></ruby>の<ruby>衆<rt>しゅう</rt></ruby>にすぎない。", exampleTrans: "人數再多，若缺乏統一指揮統御，也只不過是一群烏合之眾罷了。" },
  { id: 65, group: 7, kanji: "<ruby>牛<rt>うし</rt></ruby>の<ruby>歩<rt>あゆ</rt></ruby>み", kanjiPlain: "牛の歩み", meaning: "蝸牛爬行；像牛步般極為緩慢遲鈍的進展。", story: "牛拉車時腳步沉穩但行進速度極為緩慢。形容事情進行或工作推展的速度極慢，亦常用於議會中刻意拖延表決時的緩慢步伐（牛歩戦術）。", example: "<ruby>復興<rt>ふっこう</rt></ruby>への<ruby>道<rt>みち</rt></ruby>のりは、まさに<ruby>牛<rt>うし</rt></ruby>の<ruby>歩<rt>あゆ</rt></ruby>みのように<ruby>遅<rt>おそ</rt></ruby>い。", exampleTrans: "走向災後重建的道路，進展實在如同牛步般緩慢。" },
  { id: 66, group: 7, kanji: "<ruby>後<rt>うし</rt></ruby>ろ<ruby>指<rt>ゆび</rt></ruby>をさされる", kanjiPlain: "後ろ指をさされる", meaning: "遭人戳脊樑骨；在背後遭人指責、議論或唾罵。", story: "在某人轉身走過時，別人在他身後伸出食指指指點點。形容做了為人不齒或失德的事情，在背地裡受到社會大眾或鄰里親友的嚴厲譴責。", example: "<ruby>人<rt>ひと</rt></ruby>から<ruby>後<rt>うし</rt></ruby>ろ<ruby>指<rt>ゆび</rt></ruby>をさされるような恥ずかしい<ruby>行<rt>おこな</rt></ruby>いはするな。", exampleTrans: "千萬不要做出會讓人戳脊樑骨、在背後指指點點的丟臉勾當。" },
  { id: 67, group: 7, kanji: "<ruby>氏<rt>うじ</rt></ruby>より<ruby>育<rt>そだ</rt></ruby>ち", kanjiPlain: "氏より育ち", meaning: "教養勝於出身；後天的環境與教養比先天的家世門第更重要。", story: "「氏（うじ）」指家族姓氏、門閥出身。一個人的品格性格與能力，後天的家庭教育、個人努力與成長環境，遠比先天的血統出身來得重要得多。", example: "「<ruby>氏<rt>うじ</rt></ruby>より<ruby>育<rt>そだ</rt></ruby>ち」というが、<ruby>彼<rt>かれ</rt></ruby>の<ruby>礼儀<rt>れいぎ</rt></ruby><ruby>正<rt>ただ</rt></ruby>しさは<ruby>素晴<rt>すばら</rt></ruby>しい。", exampleTrans: "正所謂「教養勝於門第出身」，他那落落大方且規矩端正的禮貌實在令人稱讚。" },
  { id: 68, group: 7, kanji: "うそから<ruby>出<rt>で</rt></ruby>たまこと", kanjiPlain: "うそから出たまこと", meaning: "假戲真做；隨口開的玩笑或謊言，後來竟弄假成真成了事實。", story: "一開始只是無心捏造的玩笑話或隨意說說的謊言（嘘・うそ），沒想到後續的事態發展真的朝那方向演變，變成了真實（実・まこと）。", example: "<ruby>冗談<rt>じょうだん</rt></ruby>で「結婚する」と<ruby>言<rt>い</rt></ruby>っていたら、うそから<ruby>出<rt>で</rt></ruby>たまことで<ruby>本当<rt>ほんとう</rt></ruby>に<ruby>結ばれた<rt>むすばれた</rt></ruby>。", exampleTrans: "當初只是開玩笑說「我們要結婚」，沒想到假戲真做，最後竟然真的結為連理了。" },
  { id: 69, group: 7, kanji: "うそも<ruby>方<rt>ほう</rt></ruby><ruby>便<rt>べん</rt></ruby>", kanjiPlain: "うそも方便", meaning: "善意的謊言；為了顧全大局或行事順暢，有時說謊也是一種權宜之計。", story: "「方便（ほうべん）」源自佛教用語，指佛菩薩引導眾生悟道的權宜手段。在日常生活中，有時為了保護他人或緩和事態，不得不說一些善意的謊話。", example: "<ruby>彼<rt>かれ</rt></ruby>を<ruby>傷<rt>きず</rt></ruby>つけないための「うそも<ruby>方便<rt>ほうべん</rt></ruby>」だったんだ。", exampleTrans: "那是為了不傷害到他才說的善意謊言、權宜之計啊。" },
  { id: 70, group: 7, kanji: "うだつが<ruby>上<rt>あ</rt></ruby>がらない", kanjiPlain: "うだつが上がらない", meaning: "難有出頭之日；事業受阻、始終無法出人頭地或飛黃騰達。", story: "「うだつ（梲）」是指日本傳統日式建築中，為了防火與防雨而在鄰棟相鄰牆上架設的短柱或裝飾隔火小山牆。若生活貧困建不起這道體面的「うだつ」，引申為始終受困下層、抬不起頭來。", example: "<ruby>会社<rt>かいしゃ</rt></ruby>で<ruby>長年<rt>ながねん</rt></ruby><ruby>働<rt>はたら</rt></ruby>いているが、なかなかうだつが<ruby>上<rt>あ</rt></ruby>がらない。", exampleTrans: "在公司勤奮工作了許多年，卻始終鬱鬱不得志、難以出人頭地。" },
  { id: 71, group: 8, kanji: "うつつを<ruby>抜<rt>ぬ</rt></ruby>かす", kanjiPlain: "うつつを抜かす", meaning: "神魂顛倒；沉溺醉心於某事而忘記本分、喪失理智。", story: "「うつつ（現）」原本指清醒現實之意。「うつつを抜かす」意為讓現實清醒的神智全部抽空被掏走。形容過度沉迷於玩樂、嗜好或男女情愛而荒廢正事。", example: "<ruby>遊<rt>あそ</rt></ruby>びにうつつを<ruby>抜<rt>ぬ</rt></ruby>かしていて、<ruby>大事<rt>だいじ</rt></ruby>な<ruby>試験<rt>しけん</rt></ruby>に<ruby>落<rt>お</rt></ruby>ちてしまった。", exampleTrans: "過度沉迷玩樂不可自拔，導致重要的升學考試落榜了。" },
  { id: 72, group: 8, kanji: "<ruby>打<rt>う</rt></ruby>てばひびく", kanjiPlain: "打てばひびく", meaning: "心領神會、反應極為靈敏；稍加提示便立即心領神會或作出敏捷反應。", story: "敲鐘擊鼓時，鼓面一經敲打便立即發出宏亮清脆的迴響。形容人的頭腦敏銳靈活，只要稍微提點一句，立刻就能徹底領會接話或付諸行動。", example: "<ruby>彼女<rt>かのじょ</rt></ruby>は<ruby>打<rt>う</rt></ruby>てばひびくように、こちらの<ruby>意図<rt>いと</rt></ruby>をすぐに<ruby>理解<rt>りかい</rt></ruby>してくれる。", exampleTrans: "她反應非常敏銳且機靈，只要稍微提點一下，立刻就能心領神會我的意圖。" },
  { id: 73, group: 8, kanji: "<ruby>腕<rt>うで</rt></ruby>が<ruby>上<rt>あ</rt></ruby>がる", kanjiPlain: "腕が上がる", meaning: "技術長進；技術、技藝或本領大幅提升進步。", story: "「腕」在此指身手、技能本領。手藝水平向上攀升。形容經過反覆練習與努力後，某項專長手藝進步顯著。", example: "<ruby>毎日<rt>まいにち</rt></ruby><ruby>練習<rt>れんしゅう</rt></ruby>を<ruby>続<rt>つづ</rt></ruby>ければ、テニスの「<ruby>腕<rt>うで</rt></ruby>が<ruby>上<rt>あ</rt></ruby>がる」はずだ。", exampleTrans: "只要每天持續練習，網球球技一定會進步。" },
  { id: 74, group: 8, kanji: "<ruby>腕<rt>うで</rt></ruby>が<ruby>鳴<rt>な</rt></ruby>る", kanjiPlain: "腕が鳴る", meaning: "摩拳擦掌；躍躍欲試，急欲施展自己的一身絕技本領。", story: "手腕好像在雀躍作響一般。形容具備高超技術的人，遇到了絕佳發揮良機，按捺不住心中的興奮、躍躍欲試。", },
  { id: 75, group: 8, kanji: "<ruby>腕<rt>うで</rt></ruby>によりをかける", kanjiPlain: "腕によりをかける", meaning: "大顯身手；拿出看家本領、格外用心賣力地去做。", story: "「より（撚り）」是將麻繩或線搓揉旋緊加固。比喻聚集全部精氣神與手藝，竭盡所能展現最高的技巧（常用於廚藝）。", example: "<ruby>今夜<rt>こんや</rt></ruby>は<ruby>腕<rt>うで</rt></ruby>によりをかけて、ごちそうを<ruby>作<rt>つく</rt></ruby>りましょう。", exampleTrans: "今晚我要拿出看家本領大顯身手，為大家做一頓豐盛美味的大餐！" },
  { id: 76, group: 8, kanji: "うどの<ruby>大木<rt>たいぼく</rt></ruby>", kanjiPlain: "うどの大木", meaning: "大而無用的人；空有高大身材卻缺乏實用才幹本領的人。", story: "「うど（獨活）」是一種高大的草本植物，外觀看似樹木大枝幹，但內部結構鬆軟中空、脆弱不堪，既無法當木材建屋也難以承重。用來調侃體型魁梧卻無才幹者。", example: "<ruby>体<rt>からだ</rt></ruby>ばかり<ruby>大<rt>おお</rt></ruby>きくて<ruby>力仕事<rt>ちからしごと</rt></ruby>もできないようでは、うどの<ruby>大木<rt>たいぼく</rt></ruby>と<ruby>呼<rt>よ</rt></ruby>ばれてしまうぞ。", exampleTrans: "光長得高頭大馬卻連粗重活都幹不了的話，可是會被人笑成是大而無用的白大個喔。" },
  { id: 77, group: 8, kanji: "うなぎ<ruby>登<rt>のぼ</rt></ruby>り", kanjiPlain: "うなぎ登り", meaning: "直線飆升；數值、人氣或物價節節攀升、勢不可擋。", story: "鰻魚（うなぎ）體表光滑滑膩，在逆流向上攀登瀑布陡壁時動作敏捷且直衝向上。比喻氣溫、股價、支持率等數值極為迅猛地急遽上升。", example: "<ruby>新曲<rt>しんきょく</rt></ruby>のヒットで、<ruby>彼女<rt>かのじょ</rt></ruby>の<ruby>人気<rt>にんき</rt></ruby>はうなぎ<ruby>登<rt>のぼ</rt></ruby>りだ。", exampleTrans: "隨著新單曲的大受歡迎，她的人氣如同直線飆升、節節高升。" },
  { id: 78, group: 8, kanji: "うのまねをするからす", kanjiPlain: "うのまねをするからす", meaning: "東施效顰；盲目模仿實力高過自己的人，結果自討苦吃甚至招致滅亡。", story: "源自日本古典說話故事。烏鴉（カラス）羨慕鸕鶿（鵜・う）能夠潛入深水捕魚，自己也跟著一頭鑽入水中捕魚，結果羽毛全被浸濕沉底溺水。告誡人切莫不自量力盲從仿效。", example: "<ruby>実力<rt>じつりょく</rt></ruby>も<ruby>知<rt>し</rt></ruby>らずにプロの<ruby>真似<rt>まね</rt></ruby>をしても、「うのまねをするからす」になるだけだ。", exampleTrans: "不掂掂自己的實力就盲目模仿職業高手，只會變成東施效顰、自取其辱罷了。" },
  { id: 79, group: 8, kanji: "<ruby>馬<rt>うま</rt></ruby>が<ruby>合<rt>あ</rt></ruby>う", kanjiPlain: "馬が合う", meaning: "意氣相投；性格合得來、彼此非常投緣。", story: "源於騎馬術語。騎士與馬匹性情彼此配合默契良好，奔馳順暢。引申為人與人之間性格相契合、相處格外融洽自在。", example: "<ruby>彼<rt>かれ</rt></ruby>とは<ruby>初対面<rt>しょたいめん</rt></ruby>のときから<ruby>不思議<rt>ふしぎ</rt></ruby>と<ruby>馬<rt>うま</rt></ruby>が<ruby>合<rt>あ</rt></ruby>った。", exampleTrans: "從第一次見面開始，我和他就感到不可思議地非常投緣、合得來。" },
  { id: 80, group: 8, kanji: "<ruby>馬<rt>うま</rt></ruby>の<ruby>耳<rt>みみ</rt></ruby>に<ruby>念仏<rt>ねんぶつ</rt></ruby>", kanjiPlain: "馬の耳に念仏", meaning: "對牛彈琴；白費唇舌，跟聽不懂或毫無感受力的人講深奧有益的道理。", story: "對著完全不懂佛法的馬匹耳朵念誦深奧的佛經念佛（念仏・ねんぶつ），馬匹絲毫無動於衷。比喻給予極有價值的忠告或道理，對方卻完全無法領會。", example: "いくら<ruby>注意<rt>ちゅうい</rt></ruby>しても<ruby>聞<rt>き</rt></ruby>き<ruby>流<rt>なが</rt></ruby>すから、まさに「<ruby>馬<rt>うま</rt></ruby>の<ruby>耳<rt>みみ</rt></ruby>に<ruby>念仏<rt>ねんぶつ</rt></ruby>」だ。", exampleTrans: "無論怎麼苦口婆心提醒他，他都左耳進右耳出，簡直就是對牛彈琴。" },
  { id: 81, group: 9, kanji: "<ruby>産<rt>う</rt></ruby>みの<ruby>親<rt>おや</rt></ruby>より<ruby>育<rt>そだ</rt></ruby>ての<ruby>親<rt>おや</rt></ruby>", kanjiPlain: "産みの親より育ての親", meaning: "養育之恩大於生育之恩；長年悉心撫育的恩情勝過單純的血緣出生。", story: "單純只是將孩子生下來（生みの親），遠不如長年含辛茹苦細心呵護撫養長大（育ての親）所付出的恩情深厚。強調養育過程的陪伴與辛勞最為珍貴。", example: "「<ruby>産<rt>う</rt></ruby>みの<ruby>親<rt>おや</rt></ruby>より<ruby>育<rt>そだ</rt></ruby>ての<ruby>親<rt>おや</rt></ruby>」というように、<ruby>私<rt>わたし</rt></ruby>を<ruby>育<rt>そだ</rt></ruby>ててくれた<ruby>伯母<rt>おば</rt></ruby>に<ruby>深<rt>ふか</rt></ruby>く<ruby>感謝<rt>かんしゃ</rt></ruby>している。", exampleTrans: "正所謂養育之恩大於生育之情，我由衷感謝撫養我長大的伯母。" },
  { id: 82, group: 9, kanji: "<ruby>裏<rt>うら</rt></ruby>をかく", kanjiPlain: "裏をかく", meaning: "出其不意、反將一軍；識破並利用對方的心理預期，反制對方。", story: "走在對手算計佈局的背後（裏）。利用對手原以為自己會採取的常規思維，刻意反其道而行，讓對手措手不及。", example: "<ruby>相手<rt>あいて</rt></ruby>の<ruby>裏<rt>うら</rt></ruby>をかく<ruby>作戦<rt>さくせん</rt></ruby>で、<ruby>見事<rt>みごと</rt></ruby>に<ruby>逆転<rt>ぎゃくてん</rt></ruby><ruby>勝利<rt>しょうり</rt></ruby>を<ruby>収<rt>おさ</rt></ruby>めた。", exampleTrans: "採取了反將一軍、出其不意的戰術，精彩地贏得了逆轉勝。" },
  { id: 83, group: 9, kanji: "<ruby>売<rt>う</rt></ruby>り<ruby>言<rt>こと</rt></ruby><ruby>葉<rt>ば</rt></ruby>に<ruby>買<rt>か</rt></ruby>い<ruby>言<rt>こと</rt></ruby><ruby>葉<rt>ば</rt></ruby>", kanjiPlain: "売り言葉に買い言葉", meaning: "唇槍舌劍、惡言相向；對方口出惡言挑釁，自己也毫不示弱反唇相譏。", story: "對方開口挑釁如同「兜售言詞（売り言葉）」，自己嚥不下這口氣跟著回嗆回去如同「買入言詞（買い言葉）」。形容雙方互不相讓的言語謾罵衝突。", example: "「<ruby>売<rt>う</rt></ruby>り<ruby>言葉<rt>ことば</rt></ruby>に<ruby>買<rt>か</rt></ruby>い<ruby>言葉<rt>ことば</rt></ruby>」で、つまらないことから<ruby>大喧嘩<rt>おおげんか</rt></ruby>になってしまった。", exampleTrans: "因為彼此互相反唇相譏、惡言相向，結果為了一點雞毛蒜皮的小事大吵了一架。" },
  { id: 84, group: 9, kanji: "うりのつるにはなすびはならぬ", kanjiPlain: "うりのつるにはなすびはならぬ", meaning: "種瓜得瓜，種豆得豆；龍生龍鳳生鳳，平凡的父母生不出非凡的孩子。", story: "瓜藤上只會結出瓜果，絕不可能長出茄子（茄子・なすび）。比喻因果必然相符，原因如何，結果必定相稱，也常用來比喻血統稟賦的代代相傳。", example: "「うりのつるにはなすびはならぬ」で、<ruby>音楽家<rt>おんがくか</rt></ruby>の<ruby>子<rt>こ</rt></ruby>はやはり<ruby>音楽<rt>おんがく</rt></ruby>のセンスがある。", exampleTrans: "正如俗話說種瓜得瓜，音樂家的孩子果然從小就展現出音樂天賦。" },
  { id: 85, group: 9, kanji: "うり<ruby>二<rt>ふた</rt></ruby>つ", kanjiPlain: "うり二つ", meaning: "如出一轍；一模一樣，宛如一個模子印出來的。", story: "把甜瓜（瓜・うり）從正中間一刀切成兩半，兩半瓜瓣的形狀、紋路與輪廓完全相同。常用來形容相貌或特徵極為酷似的雙胞胎或父子母女。", example: "<ruby>彼<rt>かれ</rt></ruby>は<ruby>父親<rt>ちちおや</rt></ruby>の<ruby>若<rt>わか</rt></ruby>い<ruby>頃<rt>ころ</rt></ruby>の<ruby>写真<rt>しゃしん</rt></ruby>とうり<ruby>二<rt>ふた</rt></ruby>つだ。", exampleTrans: "他長得跟父親年輕時的照片一模一樣、如出一轍。" },
  { id: 86, group: 9, kanji: "うわさをすれば<ruby>影<rt>かげ</rt></ruby>がさす", kanjiPlain: "うわさをすれば影がさす", meaning: "說曹操，曹操就到；才剛在談論某人，該人就恰好出現了。", story: "才剛剛在背後談論某人的八卦傳聞（噂・うわさ），該人的身影（影・かげ）隨即就映照在眼前。相當於中文的「說曹操，曹操到」。", example: "「うわさをすれば<ruby>影<rt>かげ</rt></ruby>がさす」で、ちょうど<ruby>話<rt>はなし</rt></ruby>をしていた<ruby>田中<rt>たなか</rt></ruby>さんがやって<ruby>来<rt>き</rt></ruby>た。", exampleTrans: "真是說曹操曹操到，剛在聊田中先生，他本人就恰巧走過來了。" },
  { id: 87, group: 9, kanji: "<ruby>上<rt>うわ</rt></ruby><ruby>前<rt>まえ</rt></ruby>をはねる", kanjiPlain: "上前をはねる", meaning: "從中盤剝抽成；從他人的正當利益或工資中暗中抽取一部分據為己有。", story: "「上前」指利潤或售價中表面多加出的成數。「はねる（撥ねる）」為彈開或克扣。比喻中介人或上級利用職權中飽私囊，暗中抽取提成油水。", example: "<ruby>労働者<rt>ろうどうしゃ</rt></ruby>の<ruby>賃金<rt>ちんぎん</rt></ruby>から<ruby>上前<rt>うわまえ</rt></ruby>をはねるような<ruby>行為<rt>こうい</rt></ruby>は<ruby>許<rt>ゆる</rt></ruby>されない。", exampleTrans: "從勞工血汗工資中暗中剋扣盤剝抽成的惡劣行為是絕不被允許的。" },
  { id: 88, group: 9, kanji: "<ruby>雲<rt>うん</rt></ruby><ruby>泥<rt>でい</rt></ruby>の<ruby>差<rt>さ</rt></ruby>", kanjiPlain: "雲泥の差", meaning: "天壤之別；雲泥之別，兩者差距極其懸殊。", story: "出自白居易《傷友》詩。一個高高在上的天邊白雲，一個深陷地底的污濁爛泥。形容地位、能力或品質相差極大，判若雲泥。", example: "プロとアマチュアの<ruby>実力<rt>じつりょく</rt></ruby>には、まさに<ruby>雲泥<rt>うんでい</rt></ruby>の<ruby>差<rt>さ</rt></ruby>がある。", exampleTrans: "職業選手與業餘選手的實力之間，確實有著天壤之別。" },
  { id: 89, group: 9, kanji: "<ruby>得手<rt>えて</rt></ruby>に<ruby>帆<rt>ほ</rt></ruby>を<ruby>上<rt>あ</rt></ruby>げる", kanjiPlain: "得手に帆を上げる", meaning: "順水推舟；在遇到順境或能發揮自己拿手強項時，順勢抓住良機奮勇前進。", story: "「得手（えて）」為擅長之事；也指利於航行的順風（得風）。形容在迎來拿手領域或順境的大好良機時，毫不猶豫地揚起風帆順勢大展宏圖。", example: "<ruby>得意<rt>とくい</rt></ruby>なデザインの<ruby>仕事<rt>しごと</rt></ruby>を<ruby>任<rt>まか</rt></ruby>され、<ruby>得手<rt>えて</rt></ruby>に<ruby>帆<rt>ほ</rt></ruby>を<ruby>上<rt>あ</rt></ruby>げるように<ruby>活躍<rt>かつやく</rt></ruby>した。", exampleTrans: "被託付了最拿手的設計工作，他如順水推舟揚起風帆般大展身手、表現亮眼。" },
  { id: 90, group: 9, kanji: "えびでたいをつる", kanjiPlain: "えびでたいをつる", meaning: "一本萬利；拋磚引玉，用極微小的代價獲取巨大的回報收益。", story: "用微小便宜的小蝦子（海老・えび）當釣餌，竟釣起了昂貴稀有的大鯛魚（鯛・たい）。相當於中文的「拋磚引玉」或「以小博大」。", example: "わずかなお<ruby>土産<rt>みやげ</rt></ruby>を<ruby>渡<rt>わた</rt></ruby>したら<ruby>高級<rt>こうきゅう</rt></ruby>メロンを<ruby>頂<rt>いただ</rt></ruby>き、えびでたいをつる<ruby>結果<rt>けっか</rt></ruby>になった。", exampleTrans: "送了對方一點微薄的伴手禮，沒想到卻收到了頂級哈密瓜回禮，真成了以小博大、拋磚引玉。" },
  { id: 91, group: 10, kanji: "えりを<ruby>正<rt>ただ</rt></ruby>す", kanjiPlain: "えりを正す", meaning: "端正態度；整飭儀容，以嚴肅恭敬的心情面對。", story: "「襟（えり）」指衣服的衣領。原本指把歪斜的衣領拉正整理好。引申為收起輕浮態度，以端莊、嚴肅且端正的心境重新振作或聆聽教誨。", example: "<ruby>先輩<rt>せんぱい</rt></ruby>の<ruby>真剣<rt>しんけん</rt></ruby>な<ruby>助言<rt>じょげん</rt></ruby>を<ruby>前<rt>まえ</rt></ruby>に、えりを<ruby>正<rt>ただ</rt></ruby>して<ruby>話<rt>はなし</rt></ruby>を<ruby>聞<rt>き</rt></ruby>いた。", exampleTrans: "面對前輩誠懇認真的建言，我端正態度、嚴肅恭敬地聆聽。" },
  { id: 92, group: 10, kanji: "<ruby>縁<rt>えん</rt></ruby>の<ruby>下<rt>した</rt></ruby>の<ruby>力<rt>ちから</rt></ruby><ruby>持<rt>も</rt></ruby>ち", kanjiPlain: "縁の下の力持ち", meaning: "無名英雄；在幕後默默付出汗水、不求名利的奉獻者。", story: "日本傳統房屋地板下方（縁の下）的柱子，承載著整間屋子的重量卻終年隱身暗處無人注意。比喻在暗中默默付出極大努力來支持整個團隊的大功臣。", example: "<ruby>彼<rt>かれ</rt></ruby>はまさにイベントを<ruby>成功<rt>せいこう</rt></ruby>に<ruby>導<rt>みちび</rt></ruby>いた「<ruby>縁<rt>えん</rt></ruby>の<ruby>下<rt>した</rt></ruby>の<ruby>力持<rt>ちからも</rt></ruby>ち」だ。", exampleTrans: "他是讓活動順利圓滿成功的無名英雄、幕後大功臣。" },
  { id: 93, group: 10, kanji: "<ruby>老<rt>お</rt></ruby>いては<ruby>子<rt>こ</rt></ruby>に<ruby>従<rt>したが</rt></ruby>え", kanjiPlain: "老いては子に従え", meaning: "老而從子；年事已高時莫要固執，凡事宜順從聽取子女的意見與照顧。", story: "源自儒家三從之說（幼從父、嫁從夫、老從子）。人到了年邁體衰之際，不必再頑固堅持主見，多聽從體貼成熟子女的引導與安排才是明智安詳之道。", example: "「<ruby>老<rt>お</rt></ruby>いては<ruby>子<rt>こ</rt></ruby>に<ruby>従<rt>したが</rt></ruby>え」の<ruby>言葉<rt>ことば</rt></ruby><ruby>通<rt>どお</rt></ruby>り、<ruby>母<rt>はは</rt></ruby>は<ruby>素直<rt>すなお</rt></ruby>に<ruby>私<rt>わたし</rt></ruby>の<ruby>提案<rt>ていあん</rt></ruby>を<ruby>受<rt>う</rt></ruby>け<ruby>入<rt>い</rt></ruby>れてくれた。", exampleTrans: "正如俗話說「老而從子」，母親非常坦率且欣然地接受了我的提議。" },
  { id: 94, group: 10, kanji: "<ruby>負<rt>お</rt></ruby>うた<ruby>子<rt>こ</rt></ruby>に<ruby>教<rt>おし</rt></ruby>えられて<ruby>浅<rt>あさ</rt></ruby><ruby>瀬<rt>せ</rt></ruby>を<ruby>渡<rt>わた</rt></ruby>る", kanjiPlain: "負うた子に教えられて浅瀬を渡る", meaning: "見微知著、不恥下問；即使是長輩智者，有時也會從幼小無知者身上學到寶貴經驗。", story: "背著幼童過河的父母，反而被背上的孩子指出「那邊的水比較淺喔」。比喻有閱歷的成年人或高手，有時也能從資歷淺薄者的直覺中得到啟發與指點。", example: "<ruby>後輩<rt>こうはい</rt></ruby>の<ruby>指摘<rt>してき</rt></ruby>でミスに気づき、まさに「<ruby>負<rt>お</rt></ruby>うた<ruby>子<rt>こ</rt></ruby>に<ruby>教<rt>おし</rt></ruby>えられて<ruby>浅瀬<rt>あさせ</rt></ruby>を<ruby>渡<rt>わた</rt></ruby>る」だった。", exampleTrans: "因為後輩的一句無心提醒才察覺到了錯誤，真可謂是向晚輩受教學習了。" },
  { id: 95, group: 10, kanji: "<ruby>大<rt>おお</rt></ruby>きい<ruby>顔<rt>かお</rt></ruby>をする", kanjiPlain: "大きい顔をする", meaning: "趾高氣揚、狂妄自大；自以為了不起而表現得十分神氣。", story: "帶著一張傲慢無比的表情神態，在人群中大搖大擺。比喻自恃功勞、身分或地位，而在眾人面前擺出高人一等的傲慢姿態。", example: "<ruby>少<rt>すこ</rt></ruby>し<ruby>成績<rt>せいせき</rt></ruby>が<ruby>良<rt>よ</rt></ruby>いからといって、<ruby>大<rt>おお</rt></ruby>きい<ruby>顔<rt>かお</rt></ruby>をするな。", exampleTrans: "不能因為成績稍微好了一點，就在大家面前趾高氣揚、神氣活現。" },
  { id: 96, group: 10, kanji: "<ruby>大<rt>おお</rt></ruby>きな<ruby>口<rt>くち</rt></ruby>をきく", kanjiPlain: "大きな口をきく", meaning: "說大話；誇誇其談、說大話吹噓自己。", story: "「口をきく」為開口說話。張大嘴巴說出超過自己實際能力或身分的狂言豪語。形容誇大其詞、好說大話吹牛。", example: "<ruby>大<rt>おお</rt></ruby>きな<ruby>口<rt>くち</rt></ruby>をきく<ruby>前<rt>まえ</rt></ruby>に、まずは<ruby>自分<rt>じぶん</rt></ruby>の<ruby>仕事<rt>しごと</rt></ruby>をしっかりやりなさい。", exampleTrans: "在開口說大話吹噓之前，先把自己手頭的工作踏實做好吧。" },
  { id: 97, group: 10, kanji: "<ruby>大手<rt>おおで</rt></ruby>を<ruby>振<rt>ふ</rt></ruby>る", kanjiPlain: "大手を振る", meaning: "大搖大擺；堂堂正正、毫無顧忌羞愧地在眾人面前昂首闊步。", story: "雙臂大幅度擺動向前邁步。形容沒有任何愧疚或心虛之處，態度光明磊落、毫無顧忌地公然行動；有時亦可用於批評某人肆無忌憚。", example: "<ruby>潔白<rt>けっぱく</rt></ruby>が<ruby>証明<rt>しょうめい</rt></ruby>されたので、これからは<ruby>大手<rt>おおて</rt></ruby>を<ruby>振<rt>ふ</rt></ruby>って<ruby>歩<rt>ある</rt></ruby>ける。", exampleTrans: "既然清白已經得到證明，從今以後就能堂堂正正、昂首闊步地走在路上了。" },
  { id: 98, group: 10, kanji: "<ruby>大<rt>おお</rt></ruby><ruby>見<rt>み</rt></ruby><ruby>得<rt>え</rt></ruby>を<ruby>切<rt>き</rt></ruby>る", kanjiPlain: "大見得を切る", meaning: "誇下海口；當眾大張旗鼓地擺出豪邁架勢、立下豪言壯語。", story: "源自歌舞伎用語。「見得（みえ）を切る」是演員在高潮情節時擺出定格亮相的誇張帥氣姿態。引申為在眾人面前大張旗鼓地放話或做出極為自信的誇口保證。", example: "「<ruby>絶対<rt>ぜったい</rt></ruby>に<ruby>優勝<rt>ゆうしょう</rt></ruby>する」と<ruby>大見得<rt>おおみえ</rt></ruby>を<ruby>切<rt>き</rt></ruby>ったからには、<ruby>負<rt>ま</rt></ruby>けられない。", exampleTrans: "既然已經當眾誇下海口說「絕對要拿冠軍」，那就絕對不能輸。" },
  { id: 99, group: 10, kanji: "<ruby>大<rt>おお</rt></ruby><ruby>目<rt>め</rt></ruby>に<ruby>見<rt>み</rt></ruby>る", kanjiPlain: "大目に見る", meaning: "寬大為懷；睜一隻眼閉一隻眼、不予深究追究。", story: "用寬廣寬容的目光（大目）來看待。指對他人的過失、小瑕疵採取寬鬆寬恕的態度，不予過度責難苛求。", example: "<ruby>今回<rt>こんかい</rt></ruby>のミスは<ruby>初<rt>はじ</rt></ruby>めてのことだから、<ruby>大目<rt>おおめ</rt></ruby>に<ruby>見<rt>み</rt></ruby>ることにしよう。", exampleTrans: "這次的失誤畢竟是第一次發生，就寬大為懷、不予深究追究了吧。" },
  { id: 100, group: 10, kanji: "<ruby>岡<rt>おか</rt></ruby><ruby>目<rt>め</rt></ruby><ruby>八<rt>はち</rt></ruby><ruby>目<rt>もく</rt></ruby>", kanjiPlain: "岡目八目", meaning: "當局者迷，旁觀者清；置身事外的第三者往往看得更清楚周全。", story: "圍棋用語。下棋者（當局者）因專注勝負往往容易漏看盲點，而在旁邊旁觀的人（岡目）反而能一眼看清隨後八步的好手佈局。", example: "「<ruby>岡目八目<rt>おかめはちもく</rt></ruby>」で、<ruby>第三者<rt>だいさんしゃ</rt></ruby>のほうが<ruby>冷静<rt>れいせい</rt></ruby>に<ruby>問題点<rt>もんだいてん</rt></ruby>を<ruby>見抜<rt>みぬ</rt></ruby>ける。", exampleTrans: "正所謂「旁觀者清」，身為第三者反而能更冷靜地看清問題的核心盲點。" },
  { id: 101, group: 11, kanji: "<ruby>奥<rt>おく</rt></ruby><ruby>歯<rt>ば</rt></ruby>にものがはさまる", kanjiPlain: "奥歯にものがはさまる", meaning: "吞吞吐吐；說話欲言又止、含糊其辭，讓人聽了心裡發悶著急。", story: "如同臼齒縫隙中卡了菜葉殘渣般令人難受不適。形容說話遮遮掩掩、不明確表態，彷彿話說了一半又縮回去。", example: "<ruby>奥歯<rt>おくば</rt></ruby>にものがはさまったような<ruby>言<rt>い</rt></ruby>い<ruby>方<rt>かた</rt></ruby>をしないで、はっきり<ruby>言<rt>い</rt></ruby>ってほしい。", exampleTrans: "請不要用這種吞吞吐吐、遮遮掩掩的口氣說話，有話就請直說吧。" },
  { id: 102, group: 11, kanji: "<ruby>押<rt>お</rt></ruby>しが<ruby>強<rt>つよ</rt></ruby>い", kanjiPlain: "押しが強い", meaning: "強勢進逼；主見極強、行事極具侵略性與推動力。", story: "「押し」指推力、推進力。形容交涉、談判或表達意見時非常強勢積極，甚至帶有迫使對方接受自己要求的壓迫感。", example: "<ruby>彼<rt>かれ</rt></ruby>は<ruby>押<rt>お</rt></ruby>しが<ruby>強<rt>つよ</rt></ruby>い営業マンで、どんな契約も<ruby>取<rt>と</rt></ruby>ってくる。", exampleTrans: "他是個風格極其強勢積極的業務員，無論什麼合約都能談下來。" },
  { id: 103, group: 11, kanji: "<ruby>押<rt>お</rt></ruby>しも<ruby>押<rt>お</rt></ruby>されもせぬ", kanjiPlain: "押しも押されもせぬ", meaning: "無可爭議、地位堅固；無人能動搖其崇高地位或實力。", story: "無論別人怎麼推擠壓迫，都絲毫無法撼動其位置。形容某人的地位、聲望或實力已經得到全社會公認，穩如泰山、不可動搖。", example: "<ruby>今<rt>いま</rt></ruby>や<ruby>彼<rt>かれ</rt></ruby>は<ruby>押<rt>お</rt></ruby>しも<ruby>押<rt>お</rt></ruby>されもせぬトップスターだ。", exampleTrans: "如今他已經是位居公認首位、地位無可撼動的頂級巨星了。" },
  { id: 104, group: 11, kanji: "<ruby>男<rt>おとこ</rt></ruby>は<ruby>度<rt>ど</rt></ruby><ruby>胸<rt>きょう</rt></ruby> <ruby>女<rt>おんな</rt></ruby>は<ruby>愛<rt>あい</rt></ruby>きょう", kanjiPlain: "男は度胸 女は愛きょう", meaning: "男重膽識，女重溫婉；傳統上認為男子貴在有氣魄擔當，女子貴在親切可愛。", story: "日本傳統民間對理想男女特質的俗諺比對。「度胸（どきょう）」指膽識勇氣；「愛嬌（あいきょう）」指可愛和善惹人憐愛。反映舊時代傳統文化期望。", example: "昔から「<ruby>男<rt>おとこ</rt></ruby>は<ruby>度胸<rt>どきょう</rt></ruby>、<ruby>女<rt>おんな</rt></ruby>は<ruby>愛嬌<rt>あいきょう</rt></ruby>」とよく言われたものだ。", exampleTrans: "自古以來人們常說「男子要有膽魄氣量，女子要有溫婉親和」。" },
  { id: 105, group: 11, kanji: "<ruby>音<rt>おと</rt></ruby>に<ruby>聞<rt>き</rt></ruby>く", kanjiPlain: "音に聞く", meaning: "名聞遐邇；久仰大名、經常聽聞其赫赫聲名。", story: "「音」在此指名聲、風評、傳聞。耳朵早就常常聽聞對方的大名或名聲。相當於中文的「久仰大名」。", example: "<ruby>音<rt>おと</rt></ruby>に<ruby>聞<rt>き</rt></ruby>く<ruby>名医<rt>めいい</rt></ruby>の<ruby>診察<rt>しんさつ</rt></ruby>を<ruby>受<rt>う</rt></ruby>けるため、<ruby>遠方<rt>えんぽう</rt></ruby>から訪ねた。", exampleTrans: "為了接受名聞遐邇的名醫診察，專程從遠地趕來拜訪。" },
  { id: 106, group: 11, kanji: "<ruby>同<rt>おな</rt></ruby>じ<ruby>釜<rt>かま</rt></ruby>の<ruby>飯<rt>めし</rt></ruby>を<ruby>食<rt>く</rt></ruby>う", kanjiPlain: "同じ釜の飯を食う", meaning: "吃同一鍋飯；共同生活同甘共苦、建立了深厚的手足同袍情誼。", story: "「釜（かま）」是煮飯的鐵鍋。大家同在一個屋簷下生活，吃著同一個鐵鍋煮出來的飯食。形容同窗、軍中同袍或同事共度艱苦歲月建立的深厚革命情感。", example: "<ruby>寮<rt>りょう</rt></ruby>で<ruby>同<rt>おな</rt></ruby>じ<ruby>釜<rt>かま</rt></ruby>の<ruby>飯<rt>めし</rt></ruby>を<ruby>食<rt>く</rt></ruby>った<ruby>仲間<rt>なかま</rt></ruby>は、<ruby>生涯<rt>しょうがい</rt></ruby>の友だ。", exampleTrans: "在宿舍裡一起同甘共苦吃同一鍋飯的同儕好友，是一輩子的摯友。" },
  { id: 107, group: 11, kanji: "<ruby>鬼<rt>おに</rt></ruby>に<ruby>金<rt>かな</rt></ruby><ruby>棒<rt>ぼう</rt></ruby>", kanjiPlain: "鬼に金棒", meaning: "如虎添翼；本就勇猛強大的人又獲得了強大助力，無人能敵。", story: "原本就力大無窮、兇猛無比的惡鬼，手中又拿上了沉重的鐵棒武器。比喻強者得到了更強大的支援工具或幫手，實力倍增。", example: "<ruby>優秀<rt>ゆうしゅう</rt></ruby>な彼がチームに加われば、まさに「<ruby>鬼<rt>おに</rt></ruby>に<ruby>金棒<rt>かなぼう</rt></ruby>」だ。", exampleTrans: "要是優秀的他能加入我們團隊，簡直就是如虎添翼、實力倍增。" },
  { id: 108, group: 11, kanji: "<ruby>鬼<rt>おに</rt></ruby>の<ruby>居<rt>い</rt></ruby>ぬ<ruby>間<rt>あいだ</rt></ruby>の<ruby>洗<rt>せん</rt></ruby><ruby>濯<rt>たく</rt></ruby>", kanjiPlain: "鬼の居ぬ間の洗濯", meaning: "山中無老虎，猴子稱大王；嚴厲管束者不在時，底下的人趁機輕鬆放鬆。", story: "「洗濯」在此有洗滌晦氣、心身放鬆舒展之意。平日令人畏懼害怕的上司、長輩或惡鬼不在跟前時，大家終於可以放下戒備自由自在地放鬆玩樂。", example: "<ruby>部長<rt>ぶちょう</rt></ruby>が<ruby>出張<rt>しゅっちょう</rt></ruby>の<ruby>日<rt>ひ</rt></ruby>は、まさに「<ruby>鬼<rt>おに</rt></ruby>の<ruby>居<rt>い</rt></ruby>ぬ<ruby>間<rt>ま</rt></ruby>の<ruby>洗濯<rt>せんたく</rt></ruby>」でのんびりできる。", exampleTrans: "經理出差的那一天，大家總算能趁著管事者不在好好放鬆喘口氣。" },
  { id: 109, group: 11, kanji: "<ruby>鬼<rt>おに</rt></ruby>の<ruby>目<rt>め</rt></ruby>に<ruby>涙<rt>なみだ</rt></ruby>", kanjiPlain: "鬼の目に涙", meaning: "鐵石心腸也會落淚；再冷酷無情嚴厲的人，偶爾也會流露慈悲憐憫之情。", story: "就連世上最殘暴凶狠的惡鬼，在看到極度悲慘感人的情景時也會忍不住掉眼淚。比喻平時最冷酷嚴苛之人，也有動容落淚的一面。", example: "いつも<ruby>厳<rt>きび</rt></ruby>しい先生が卒業式で涙ぐみ、「<ruby>鬼<rt>おに</rt></ruby>の<ruby>目<rt>め</rt></ruby>にも<ruby>涙<rt>なみだ</rt></ruby>」だと話題になった。", exampleTrans: "平時嚴肅無比的老師在畢業典禮上泛紅了眼眶，成了大家口中「鐵漢亦有柔情」的溫馨話題。" },
  { id: 110, group: 11, kanji: "<ruby>鬼<rt>おに</rt></ruby>も<ruby>十<rt>じゅう</rt></ruby><ruby>八<rt>はち</rt></ruby><ruby>番<rt>ばん</rt></ruby><ruby>茶<rt>ちゃ</rt></ruby>も<ruby>出<rt>で</rt></ruby>ばな", kanjiPlain: "鬼も十八番茶も出ばな", meaning: "女大十八變；女孩到了青春妙齡自然楚楚動人，如同粗茶剛泡好時也芳香醇美。", story: "即便是相貌粗鄙如鬼的女子，到了十八歲青春盛年也會有一番魅力；即便是粗劣的番茶，剛沖第一道沸水（出花・でばな）時也香氣四溢。形容青春芳華的美好時期。", example: "「<ruby>鬼<rt>おに</rt></ruby>も<ruby>十八<rt>じゅうはち</rt></ruby><ruby>番茶<rt>ばんちゃ</rt></ruby>も<ruby>出<rt>で</rt></ruby>ばな」というように、すっかり綺麗になったね。", exampleTrans: "正如俗話說女大十八變，如今真是變得楚楚動人、十分漂亮呢。" },
  { id: 111, group: 12, kanji: "<ruby>己<rt>おのれ</rt></ruby>の<ruby>頭<rt>あたま</rt></ruby>のはえを<ruby>追<rt>お</rt></ruby>え", kanjiPlain: "己の頭のはえを追え", meaning: "各人自掃門前雪；先管好自己的爛攤子，休要多管別人閒事。", story: "自己頭頂上停著的蒼蠅（蠅・はえ）都還沒揮趕乾淨，哪有閒功夫去幫別人揮蒼蠅。告誡人應先解決處理好自己的缺失缺點，莫指手畫腳管閒事。", example: "<ruby>人<rt>ひと</rt></ruby>の心配をする前に、まずは「<ruby>己<rt>おのれ</rt></ruby>の<ruby>頭<rt>あたま</rt></ruby>の<ruby>蠅<rt>はえ</rt></ruby>を<ruby>追<rt>お</rt></ruby>え」だ。", exampleTrans: "在替別人的事情操心之前，先把自己眼前的爛攤子管好吧。" },
  { id: 112, group: 12, kanji: "お<ruby>百<rt>ひゃく</rt></ruby><ruby>度<rt>ど</rt></ruby>を<ruby>踏<rt>ふ</rt></ruby>む", kanjiPlain: "お百度を踏む", meaning: "再三懇求、百般拜託；多次登門造訪苦苦哀求對方相助。", story: "源自日本神佛信仰的「お百度参り（おひゃくどまいり）」，信徒為求祈願應驗，在神社境內來回奔走膜拜百次。引申為為了求人辦事而頻繁登門拜訪相求。", example: "<ruby>借金<rt>しゃっきん</rt></ruby>のお願いのために、<ruby>親戚<rt>しんせき</rt></ruby>の家へお<ruby>百度<rt>ひゃくど</rt></ruby>を<ruby>踏<rt>ふ</rt></ruby>んだ。", exampleTrans: "為了解決資金周轉問題，三番兩次跑去親戚家苦苦登門懇求相助。" },
  { id: 113, group: 12, kanji: "<ruby>尾<rt>お</rt></ruby>ひれをつける", kanjiPlain: "尾ひれをつける", meaning: "添油加醋；言過其實，在陳述事情時捏造誇大細節。", story: "在原本單純的魚體上，額外添上巨大的魚尾與魚鰭（尾鰭・おひれ）。比喻傳話或講述事件時，惡意或無心地誇大其詞、無中生有增添虛構細節。", example: "<ruby>噂<rt>うわさ</rt></ruby><ruby>話<rt>ばなし</rt></ruby>に<ruby>尾<rt>お</rt></ruby>ひれをつけて周囲に言いふらすのは良くない。", exampleTrans: "給道聽塗說的八卦傳聞添油加醋並到處傳播，是非常不好的行為。" },
  { id: 114, group: 12, kanji: "<ruby>重<rt>おも</rt></ruby><ruby>荷<rt>に</rt></ruby>をおろす", kanjiPlain: "重荷をおろす", meaning: "卸下重擔；擺脫了繁重的負擔、責任或精神壓力。", story: "把背上沉重的行囊貨物卸在地面上。形容多年承擔的重大職責、沈重義務或心頭重壓終於圓滿告一段落，整個人頓覺輕鬆自在。", example: "<ruby>子供<rt>こども</rt></ruby>が<ruby>全員<rt>ぜんいん</rt></ruby><ruby>独立<rt>どくりつ</rt></ruby>し、ようやく<ruby>重荷<rt>おもに</rt></ruby>をおろすことができた。", exampleTrans: "孩子們全部長大成家獨立了，身為父母終於能放下肩上的千斤重擔。" },
  { id: 115, group: 12, kanji: "<ruby>親<rt>おや</rt></ruby>に<ruby>似<rt>に</rt></ruby>ぬ<ruby>子<rt>こ</rt></ruby>は<ruby>鬼<rt>おに</rt></ruby>", kanjiPlain: "親に似ぬ子は鬼", meaning: "子不肖父如惡疾；孩子性格樣貌若絲毫不似父母，常令人感嘆或非議。", story: "民間古俗語。舊時認為孩子多少都會繼承父母雙方的稟賦特質；若絲毫無半點相似，會被迷信地視為異類或不肖怪胎。現多用來比喻孩子作風與父母天差地別。", example: "「<ruby>親<rt>おや</rt></ruby>に<ruby>似<rt>に</rt></ruby>ぬ<ruby>子<rt>こ</rt></ruby>は<ruby>鬼子<rt>おにご</rt></ruby>」というが、真面目な両親からあんな奔放な子が生まれるとは。", exampleTrans: "雖說孩子不像父母令人稱奇，真沒想到那麼嚴謹的父母竟然生出了作風如此奔放的孩子。" },
  { id: 116, group: 12, kanji: "<ruby>親<rt>おや</rt></ruby>の<ruby>因<rt>いん</rt></ruby><ruby>果<rt>が</rt></ruby>が<ruby>子<rt>こ</rt></ruby>に<ruby>報<rt>むく</rt></ruby>ゆ", kanjiPlain: "親の因果が子に報ゆ", meaning: "父債子還、殃及子孫；父母所造下的罪愆惡業，報應牽連到了無辜子女身上。", story: "源自佛教因果報應思想。父母所做下的惡行禍端，惡報卻降臨在後代子孫身上承擔苦難。形容上一代的過犯殃及下一代無辜。", example: "<ruby>親<rt>おや</rt></ruby>の<ruby>因果<rt>いんが</rt></ruby>が<ruby>子<rt>こ</rt></ruby>に<ruby>報<rt>むく</rt></ruby>いるようなことがあっては決してならない。", exampleTrans: "絕對不應該發生上一代的罪業禍端牽連殃及無辜子女的悲劇。" },
  { id: 117, group: 12, kanji: "<ruby>親<rt>おや</rt></ruby>の<ruby>心<rt>こころ</rt></ruby><ruby>子<rt>こ</rt></ruby><ruby>知<rt>し</rt></ruby>らず", kanjiPlain: "親の心子知らず", meaning: "可憐天下父母心；父母深切的關愛與苦心，為人子女者往往不能理解體會。", story: "父母對子女處處牽掛、百般設想的苦口婆心，年輕不懂事的孩子往往覺得嘮叨束縛、無法領會珍惜。感嘆兩代之間的心理落差。", example: "<ruby>心配<rt>しんぱい</rt></ruby>してアドバイスしたのに反発され、まさに「<ruby>親<rt>おや</rt></ruby>の<ruby>心<rt>こころ</rt></ruby><ruby>子<rt>こ</rt></ruby><ruby>知<rt>し</rt></ruby>らず」だ。", exampleTrans: "滿心牽掛給予建議卻反而遭到強烈頂撞，真是可憐天下父母心、為人子女不知雙親苦心。" },
  { id: 118, group: 12, kanji: "<ruby>親<rt>おや</rt></ruby>のすねをかじる", kanjiPlain: "親のすねをかじる", meaning: "啃老；成年後仍依賴父母的金錢資助生活。", story: "「脛（すね）」是小腿脛骨。比喻成年子女自己不肯踏實工作自立，靠啃咬父母的骨血骨肉生活。指長年靠父母資助金援的啃老族行為。", example: "<ruby>社会人<rt>しゃかいじん</rt></ruby>になっても<ruby>働<rt>はたら</rt></ruby>かず、いつまでも<ruby>親<rt>おや</rt></ruby>のすねをかじっている。", exampleTrans: "都已經到了踏入社會的年紀卻還是不去工作，始終在老家當個啃老族。" },
  { id: 119, group: 12, kanji: "<ruby>親<rt>おや</rt></ruby>の<ruby>光<rt>ひかり</rt></ruby>は<ruby>七<rt>なな</rt></ruby><ruby>光<rt>ひかり</rt></ruby>", kanjiPlain: "親の光は七光", meaning: "庇蔭後代；仰仗父母的顯赫聲名或權勢背景獲得巨大利益（親の七光り）。", story: "父母自身散發的權勢或名望光芒，能為子女帶來加倍耀眼的庇蔭。「七（なな）」比喻倍數繁多。多指靠父母的名氣背景走後門或享有特權。", example: "<ruby>彼<rt>かれ</rt></ruby>の実力ではなく、「<ruby>親<rt>おや</rt></ruby>の<ruby>光<rt>ひかり</rt></ruby>は<ruby>七光<rt>ななひか</rt></ruby>」で採用されたのだろう。", exampleTrans: "他並不是憑真實本領，大概是靠著父母的顯赫背景與權勢庇蔭才被錄取的吧。" },
  { id: 120, group: 12, kanji: "<ruby>親<rt>おや</rt></ruby>はなくとも<ruby>子<rt>こ</rt></ruby>は<ruby>育<rt>そだ</rt></ruby>つ", kanjiPlain: "親はなくとも子は育つ", meaning: "兒孫自有兒孫福；哪怕沒有父母呵護，孩子也會自然長大成人。", story: "即便不幸失去父母雙親的照護庇護，幼小的孩子也能憑藉周遭人們的善意與自身的生命力成長茁壯。用以撫慰孤兒，或勸父母不必對孩子過度溺愛保護。", example: "「<ruby>親<rt>おや</rt></ruby>はなくとも<ruby>子<rt>こ</rt></ruby>は<ruby>育<rt>そだ</rt></ruby>つ」というから、過保護になりすぎないほうがいい。", exampleTrans: "俗話說「兒孫自有兒孫福，離了父母孩子也自會成長」，不必對孩子過度保護溺愛。" },
  { id: 121, group: 13, kanji: "<ruby>折<rt>お</rt></ruby>り<ruby>紙<rt>がみ</rt></ruby>つき", kanjiPlain: "折り紙つき", meaning: "品質有保證、公認可信；經過權威鑑定、信譽無可置疑。", story: "「折り紙（おりがみ）」在古時指江戶時代刀劍、美術品或古董的折疊式官方鑑定證書。有此鑑定書便證明是貨真價實的真品。引申為某人能力卓越或事物品質極佳、廣受公認保證。", example: "<ruby>彼<rt>かれ</rt></ruby>のプログラミングの<ruby>実力<rt>じつりょく</rt></ruby>は、<ruby>業界<rt>ぎょうかい</rt></ruby>でも<ruby>折<rt>お</rt></ruby>り<ruby>紙<rt>がみ</rt></ruby>つきだ。", exampleTrans: "他的程式撰寫實力在業界內也是公認有保證、備受推崇的。" },
  { id: 122, group: 13, kanji: "<ruby>女<rt>おんな</rt></ruby><ruby>三<rt>さん</rt></ruby><ruby>人<rt>にん</rt></ruby><ruby>寄<rt>よ</rt></ruby>ればかしましい", kanjiPlain: "女三人寄ればかしましい", meaning: "三個女人一台戲；女人聚在一起話匣子大開、熱鬧嘈雜。", story: "「かしましい（姦しい）」意為嘈雜喧鬧。漢字「姦」即由三個「女」字組合而成。形容女性群聚閒聊時氣氛熱絡吵鬧的古諺。", example: "「<ruby>女<rt>おんな</rt></ruby><ruby>三人<rt>さんにん</rt></ruby><ruby>寄<rt>よ</rt></ruby>ればかしましい」というが、カフェの<ruby>席<rt>せき</rt></ruby>から楽しそうな笑い声が絶えない。", exampleTrans: "俗話說三個女人一台戲，咖啡廳那桌不斷傳來陣陣歡樂喧鬧的笑聲。" },
  { id: 123, group: 13, kanji: "<ruby>恩<rt>おん</rt></ruby>に<ruby>着<rt>き</rt></ruby>せる", kanjiPlain: "恩に着せる", meaning: "賣人情、誇大恩惠；藉由給予幫助而擺出施恩者姿態、要求對方感恩圖報。", story: "強行把恩惠像是衣服一樣穿在對方身上（着せる）。指自己雖給予他人協助，卻頻頻提起邀功，刻意使對方背負人情負擔。", example: "<ruby>少<rt>すこ</rt></ruby>し<ruby>手伝<rt>てつだ</rt></ruby>っただけで、そんなに<ruby>恩<rt>おん</rt></ruby>に<ruby>着<rt>き</rt></ruby>せるような<ruby>言<rt>い</rt></ruby>い方をしなくてもいいのに。", exampleTrans: "不過是稍微幫了一點忙，用不著用這種居高臨下、賣弄人情的口氣說話吧。" },
  { id: 124, group: 13, kanji: "<ruby>飼<rt>か</rt></ruby>い<ruby>犬<rt>いぬ</rt></ruby>に<ruby>手<rt>て</rt></ruby>をかまれる", kanjiPlain: "飼い犬に手をかまれる", meaning: "遭家犬反咬一口；遭親信背叛、被平日悉心照顧栽培的人暗算反咬。", story: "天天親手餵養照料的家犬，竟然出其不意地回頭咬了主人的手。比喻受到自己最信任、親手栽培的部屬或親友背叛暗算。", example: "<ruby>信頼<rt>しんらい</rt></ruby>していた<ruby>部下<rt>ぶか</rt></ruby>に<ruby>裏切<rt>うらぎ</rt></ruby>られ、「<ruby>飼<rt>か</rt></ruby>い<ruby>犬<rt>いぬ</rt></ruby>に<ruby>手<rt>て</rt></ruby>をかまれる」とはこのことだ。", exampleTrans: "被自己最信任的下屬背叛出賣，真所謂是遭到家犬反咬一口。" },
  { id: 125, group: 13, kanji: "<ruby>蛙<rt>かえる</rt></ruby>の<ruby>面<rt>めん</rt></ruby>に<ruby>水<rt>みず</rt></ruby>", kanjiPlain: "蛙の面に水", meaning: "面不改色、滿不在乎；受到責備提醒依然無動於衷、厚臉皮毫不介意。", story: "青蛙（蛙・かえる）的面孔本來就習慣在水中生活，朝牠臉上潑水牠絲毫不會驚慌害怕。形容厚臉皮之人即便被當面斥責懲戒，也是毫無羞愧痛癢之意。", example: "どんなに<ruby>厳<rt>きび</rt></ruby>しく<ruby>叱<rt>しか</rt></ruby>られても、<ruby>彼<rt>かれ</rt></ruby>は「<ruby>蛙<rt>かえる</rt></ruby>の<ruby>面<rt>つら</rt></ruby>に<ruby>水<rt>みず</rt></ruby>」で反省する様子がない。", exampleTrans: "不管受到多嚴厲的斥責，他依舊滿不在乎、面不改色，完全看不出絲毫反省的模樣。" },
  { id: 126, group: 13, kanji: "<ruby>顔<rt>かお</rt></ruby>がつぶれる", kanjiPlain: "顔がつぶれる", meaning: "顏面掃地；名譽受損、尊嚴盡失失去面子。", story: "「顔」代表世俗的體面、面子與尊嚴。「つぶれる（潰れる）」是損毀破壞。形容因犯錯、醜聞或失敗而使自己在社會大眾或人前顏面無存。", example: "<ruby>部下<rt>ぶか</rt></ruby>の<ruby>不祥事<rt>ふしょうじ</rt></ruby>のせいで、リーダーの<ruby>顔<rt>かお</rt></ruby>がつぶれてしまった。", exampleTrans: "因為下屬惹出的醜聞，讓主管的顏面徹底掃地、尊嚴全失。" },
  { id: 127, group: 13, kanji: "<ruby>顔<rt>かお</rt></ruby>に<ruby>泥<rt>どろ</rt></ruby>を<ruby>塗<rt>ぬ</rt></ruby>る", kanjiPlain: "顔に泥を塗る", meaning: "玷污名聲、令其蒙羞；做出丟臉行為使父母、師長或團體名譽受損。", story: "在別人的臉龐上塗抹污泥。比喻做出不名譽或羞恥的勾當，害得對自己有恩的父母、恩師或組織蒙受奇恥大辱。", example: "<ruby>親<rt>おや</rt></ruby>の<ruby>顔<rt>かお</rt></ruby>に<ruby>泥<rt>どろ</rt></ruby>を<ruby>塗<rt>ぬ</rt></ruby>るような<ruby>不正<rt>ふせい</rt></ruby>な<ruby>行為<rt>こうい</rt></ruby>は<ruby>絶対<rt>ぜったい</rt></ruby>にしてはいけない。", exampleTrans: "絕不能做出讓父母蒙羞、玷污家庭名譽的違法不當行為。" },
  { id: 128, group: 13, kanji: "<ruby>影<rt>かげ</rt></ruby>が<ruby>薄<rt>うす</rt></ruby>い", kanjiPlain: "影が薄い", meaning: "毫無存在感；性格或外表缺乏特點、容易被人忽視遺忘。", story: "彷彿連倒映在地上的影子都十分清淡薄弱。形容某人的存在感微弱、沈默寡言，在群體之中容易被忽視；有時亦形容人病容憔悴、衰弱無神采。", example: "<ruby>彼<rt>かれ</rt></ruby>は<ruby>大人<rt>おとな</rt></ruby>しくて<ruby>影<rt>かげ</rt></ruby>が<ruby>薄<rt>うす</rt></ruby>いが、実はとても芯の強い人だ。", exampleTrans: "他平時沈默寡言且存在感不高，但實際上是個內心非常有原則骨氣的人。" },
  { id: 129, group: 13, kanji: "<ruby>影<rt>かげ</rt></ruby>も<ruby>形<rt>かたち</rt></ruby>もない", kanjiPlain: "影も形もない", meaning: "蹤影全無；消失得無影無蹤、蕩然無存。", story: "連一絲影子與輪廓都不復存在。形容原本存在的人、物品、痕跡或現象徹底消逝無蹤，一點線索殘留都沒有。", example: "<ruby>開発<rt>かいはつ</rt></ruby>が<ruby>進<rt>すす</rt></ruby>み、かつての<ruby>静<rt>しず</rt></ruby>かな<ruby>農村<rt>のうそん</rt></ruby>の<ruby>面影<rt>おもかげ</rt></ruby>は<ruby>影<rt>かげ</rt></ruby>も<ruby>形<rt>かたち</rt></ruby>もない。", exampleTrans: "隨著土地開發推進，昔日寧靜農村的樣貌已經蕩然無存、毫無蹤影了。" },
  { id: 130, group: 13, kanji: "かさにかかる", kanjiPlain: "かさにかかる", meaning: "居高臨下、仗勢凌人；自恃優勢而咄咄逼人壓迫對手。", story: "「かさ（嵩）」指體積、分量。自恃自己擁有強大的勢力、人數優勢或權威地位，仗著龐大的身段對弱小對手步步進逼施壓。", example: "<ruby>人数<rt>にんずう</rt></ruby>の<ruby>多<rt>おお</rt></ruby>さをかさに<ruby>懸<rt>か</rt></ruby>かって、<ruby>無理<rt>むり</rt></ruby>な<ruby>要求<rt>ようきゅう</rt></ruby>を<ruby>通<rt>とお</rt></ruby>そうとする。", exampleTrans: "仗著己方人多勢眾居高臨下，企圖強行通過不合理的要求。" },
  { id: 131, group: 14, kanji: "かさに<ruby>着<rt>き</rt></ruby>る", kanjiPlain: "かさに着る", meaning: "狐假虎威、仗勢欺人；藉由背後的權勢或長輩當靠山來耍威風。", story: "把上位者或權威的威勢如同雨傘斗笠（笠・かさ）一樣戴在頭頂遮蔭。形容借用父母的地位、上司的權威作為後盾來欺壓他人。", example: "<ruby>親<rt>おや</rt></ruby>の<ruby>権力<rt>けんりょく</rt></ruby>をかさに<ruby>着<rt>き</rt></ruby>て<ruby>横暴<rt>おうぼう</rt></ruby>な<ruby>振<rt>ふ</rt></ruby>る<ruby>舞<rt>ま</rt></ruby>いをする。", exampleTrans: "仗著父母的顯赫權勢當靠山，在外面為非作歹、橫行霸道。" },
  { id: 132, group: 14, kanji: "<ruby>風<rt>かざ</rt></ruby><ruby>上<rt>かみ</rt></ruby>にもおけない", kanjiPlain: "風上にもおけない", meaning: "為同類所不齒；卑鄙無恥、不配與正人君子同列。", story: "迎風的上方稱為「風上」。惡臭的東西若放在上風處，臭氣便會隨風吹往四周毒害他人。形容某人品格惡劣卑鄙，根本不配被稱為同袍或業界同僚。", example: "<ruby>仲買<rt>なかがい</rt></ruby>を<ruby>騙<rt>だま</rt></ruby>すような<ruby>商人<rt>しょうにん</rt></ruby>は、<ruby>商人<rt>しょうにん</rt></ruby>の<ruby>風上<rt>かざかみ</rt></ruby>にもおけない。", exampleTrans: "連同行都詐騙的黑心商人，根本不配被稱作生意人、為全行所不齒。" },
  { id: 133, group: 14, kanji: "<ruby>稼<rt>かせ</rt></ruby>ぐに<ruby>追<rt>お</rt></ruby>いつく<ruby>貧<rt>びん</rt></ruby><ruby>乏<rt>ぼう</rt></ruby>なし", kanjiPlain: "稼ぐに追いつく貧乏なし", meaning: "勤勞致富；只要腳踏實地辛勤工作，貧困便追不上腳步。", story: "比喻貧窮雖然緊追在後，但只要每天勤勉不懈地賺錢工作（稼ぐ），前進的腳步自然遠遠快過貧困的侵襲。勉勵人天道酬勤。", example: "「<ruby>稼<rt>かせ</rt></ruby>ぐに<ruby>追<rt>お</rt></ruby>いつく<ruby>貧乏<rt>びんぼう</rt></ruby>なし」を<ruby>信条<rt>しんじょう</rt></ruby>に、<ruby>毎日<rt>まいにち</rt></ruby><ruby>汗<rt>あせ</rt></ruby>を<ruby>流<rt>なが</rt></ruby>して<ruby>働<rt>はたら</rt></ruby>く。", exampleTrans: "將「天道酬勤、勤勞免於匱乏」奉為人生信條，每天揮灑汗水辛勤工作。" },
  { id: 134, group: 14, kanji: "<ruby>肩<rt>かた</rt></ruby>すかしをくう", kanjiPlain: "肩すかしをくう", meaning: "撲了個空；滿腔期待卻遭人冷淡閃避應付、落得無處著力。", story: "源自相撲技法「肩透かし（かたすかし）」。對手猛烈衝撞過來時，自己突然閃身拍其肩膀使其向前撲空摔倒。比喻氣勢洶洶前來交涉卻被對方輕巧閃過、自討無趣。", example: "<ruby>気合<rt>きあい</rt></ruby>を<ruby>入<rt>い</rt></ruby>れて<ruby>議論<rt>ぎろん</rt></ruby>を<ruby>挑<rt>いど</rt></ruby>んだが、<ruby>相手<rt>あいて</rt></ruby>が<ruby>適当<rt>てきとう</rt></ruby>に<ruby>流<rt>なが</rt></ruby>すので<ruby>肩<rt>かた</rt></ruby>すかしをくった。", exampleTrans: "滿懷鬥志前來找他辯論，沒想到對方卻隨意敷衍帶過，讓我撲了個空、好不沒趣。" },
  { id: 135, group: 14, kanji: "かたずをのむ", kanjiPlain: "かたずをのむ", meaning: "屏息以待；因極度緊張不安而嚥下口水、屏住呼吸注視發展。", story: "「かたず（固唾）」指極度緊張時口中凝結聚縮的口水。在千鈞一髮或決定命運的瞬間，眾人緊張得吞下口水不敢作聲。", example: "<ruby>大勢<rt>おおぜい</rt></ruby>の<ruby>観客<rt>かんきゃく</rt></ruby>が、かたずをのんで<ruby>最後<rt>さいご</rt></ruby>のPKを<ruby>見守<rt>みまも</rt></ruby>った。", exampleTrans: "全場觀眾無不屏息以待、緊張得不敢出聲，注視著最後一顆罰球點球。" },
  { id: 136, group: 14, kanji: "<ruby>肩<rt>かた</rt></ruby>の<ruby>荷<rt>に</rt></ruby>がおりる", kanjiPlain: "肩の荷がおりる", meaning: "如釋重負；沉重的責任或牽掛心事圓滿完成，整個人輕鬆釋懷。", story: "一直沉重壓在肩膀上的擔子貨物終於放了下來。形容長期肩負的繁重任務、職責或擔憂順利結束，心情由緊繃轉為輕鬆舒坦。", example: "<ruby>大<rt>おお</rt></ruby>きなプロジェクトが<ruby>無事<rt>ぶじ</rt></ruby>に<ruby>終了<rt>しゅうりょう</rt></ruby>し、ようやく<ruby>肩<rt>かた</rt></ruby>の<ruby>荷<rt>に</rt></ruby>がおりた。", exampleTrans: "大型專案終於平安順利圓滿落幕，整個人總算如釋重負、放下了心頭大石。" },
  { id: 137, group: 14, kanji: "<ruby>肩<rt>かた</rt></ruby><ruby>身<rt>み</rt></ruby>がせまい", kanjiPlain: "肩身がせまい", meaning: "自慚形穢、抬不起頭；因感到內疚缺點或自卑，在眾人面前感到十分不自在。", story: "「肩身」指肩膀與身體的外在身段。在社會人際壓力下覺得自身渺小短缺，彷彿肩膀縮得窄小狹隘。形容感到慚愧丟臉、缺乏立足自信的心態。", example: "<ruby>成績<rt>せいせき</rt></ruby>が<ruby>振<rt>ふ</rt></ruby>るわず、クラスで<ruby>少<rt>すこ</rt></ruby>し<ruby>肩身<rt>かたみ</rt></ruby>がせまい<ruby>思<rt>おも</rt></ruby>いをしている。", exampleTrans: "因為成績表現不太理想，在班上總覺得有點自慚形穢、抬不起頭來。" },
  { id: 138, group: 14, kanji: "<ruby>肩<rt>かた</rt></ruby>を<ruby>怒<rt>いか</rt></ruby>らせる", kanjiPlain: "肩を怒らせる", meaning: "昂首聳肩、擺架子；挺胸聳起肩膀以示威嚴威風或威嚇他人。", story: "「怒らせる（いからせる）」在此為聳立高聳之意。走路時把雙肩聳得高高、晃動身軀大步走。比喻刻意裝腔作勢擺架子，或藉由威嚇姿態震懾旁人。", example: "<ruby>彼<rt>かれ</rt></ruby>は<ruby>肩<rt>かた</rt></ruby>を<ruby>怒<rt>いか</rt></ruby>らせて、いかにも<ruby>偉<rt>えら</rt></ruby>そうに<ruby>部屋<rt>へや</rt></ruby>へ<ruby>入<rt>はい</rt></ruby>ってきた。", exampleTrans: "他聳著肩膀、擺足了架子，一副不可一世的傲慢模樣走進房間。" },
  { id: 139, group: 14, kanji: "<ruby>肩<rt>かた</rt></ruby>を<ruby>入<rt>い</rt></ruby>れる", kanjiPlain: "肩を入れる", meaning: "極力偏袒、傾力支持；特別看重並給予某人毫無保留的庇護資助。", story: "把自己的肩膀貼入對方的背後幫忙推動發力。形容對特定的某個人或團體傾注全部熱情全力給予偏愛、支持或護航。", example: "<ruby>社長<rt>しゃちょう</rt></ruby>が<ruby>特別<rt>とくべつ</rt></ruby>に<ruby>肩<rt>かた</rt></ruby>を<ruby>入<rt>い</rt></ruby>れている<ruby>新規<rt>しんき</rt></ruby><ruby>事業<rt>じぎょう</rt></ruby>だから、<ruby>失敗<rt>しっぱい</rt></ruby>はできない。", exampleTrans: "因為這是社長傾注全力支持庇護的全新事業計畫，絕對不允許失敗。" },
  { id: 140, group: 14, kanji: "<ruby>火<rt>か</rt></ruby><ruby>中<rt>ちゅう</rt></ruby>の<ruby>栗<rt>くり</rt></ruby>を<ruby>拾<rt>ひろ</rt></ruby>う", kanjiPlain: "火中の栗を拾う", meaning: "火中取栗；受人挑撥利用去冒極大危險，自己承擔苦果卻讓他人坐享其成。", story: "出自伊索寓言與拉封丹寓言。猴子誘騙貓咪將爪子伸進滾燙的柴火爐灶中掏出烤熟的栗子，貓爪被燙得焦黑劇痛，栗子卻全被猴子吃光。", example: "<ruby>彼<rt>かれ</rt></ruby>の甘言に乗せられて、<ruby>火中<rt>かちゅう</rt></ruby>の<ruby>栗<rt>くり</rt></ruby>を<ruby>拾<rt>ひろ</rt></ruby>うような真似はやめなさい。", exampleTrans: "千萬不要被他的甜言蜜語哄騙，跑去幹那種替人火中取栗、白白冒險受害的蠢事。" },
  { id: 141, group: 15, kanji: "<ruby>勝<rt>か</rt></ruby>ってかぶとの<ruby>緒<rt>お</rt></ruby>をしめよ", kanjiPlain: "勝ってかぶとの緒をしめよ", meaning: "居安思危；戰勝之後更要繫緊頭盔帶子，警惕在勝利時切莫鬆懈大意。", story: "戰國武將北條氏綱遺訓。打贏勝仗後最容易因得意洋洋放鬆戒備而遭敵反撲，因此戰勝時更要繫緊頭盔繩索（兜の緒・かぶとのお）。戒驕戒躁。", example: "<ruby>予選<rt>よせん</rt></ruby>をトップで通過したが、「<ruby>勝<rt>か</rt></ruby>って<ruby>兜<rt>かぶと</rt></ruby>の<ruby>緒<rt>お</rt></ruby>を<ruby>締<rt>し</rt></ruby>めよ」で<ruby>決勝<rt>けっしょう</rt></ruby>に臨もう。", exampleTrans: "雖然以第一名預賽出線，但秉持「勝不驕、居安思危」的精神迎接決賽吧。" },
  { id: 142, group: 15, kanji: "<ruby>買<rt>か</rt></ruby>って<ruby>出<rt>で</rt></ruby>る", kanjiPlain: "買って出る", meaning: "挺身而出；主動自告奮勇承攬下無人願意接手的苦差事或棘手工作。", story: "「買って」本意是花錢買下，引申為哪怕自討苦吃，也心甘情願自告奮勇挺身而出、主動擔下大家退避三舍的繁重責任。", example: "<ruby>誰<rt>だれ</rt></ruby>もやりたがらない<ruby>幹事<rt>かんじ</rt></ruby>の<ruby>役<rt>やく</rt></ruby>を、<ruby>彼<rt>かれ</rt></ruby>が<ruby>自<rt>みずか</rt></ruby>ら<ruby>買<rt>か</rt></ruby>って<ruby>出<rt>で</rt></ruby>てくれた。", exampleTrans: "誰都不願意接下的主辦籌備苦差事，他主動挺身而出、自告奮勇接了下來。" },
  { id: 143, group: 15, kanji: "<ruby>角<rt>かど</rt></ruby>が<ruby>取<rt>と</rt></ruby>れる", kanjiPlain: "角が取れる", meaning: "變得圓滑洗練；隨著年齡歷練增加，性格中的銳角稜角與脾氣逐漸變得圓融溫和。", story: "原本尖銳有刺的石塊經由長年河水激流沖刷碰撞，尖角（角）磨損脱落變得平滑圓潤。比喻年輕時暴躁要強的脾氣隨歲月沉澱而變得成熟圓滑。", example: "<ruby>昔<rt>むかし</rt></ruby>は尖っていた<ruby>彼<rt>かれ</rt></ruby>も、<ruby>年齢<rt>ねんれい</rt></ruby>を重ねてすっかり<ruby>角<rt>かど</rt></ruby>が<ruby>取<rt>と</rt></ruby>れた。", exampleTrans: "從前個性充滿稜角刺人的他，如今經過歲月沉澱也變得非常圓滑溫和了。" },
  { id: 144, group: 15, kanji: "<ruby>金<rt>かね</rt></ruby>がものをいう", kanjiPlain: "金がものをいう", meaning: "有錢能使鬼推磨；金錢具有強大的威力與決定性的影響力。", story: "「ものをいう（物を言う）」意為能發揮決定性效力。形容在資本現實社會中，金錢往往比道理、才幹或情面更能左右事情的成敗決定。", example: "<ruby>世<rt>よ</rt></ruby>の<ruby>中<rt>なか</rt></ruby>は<ruby>理想<rt>りそう</rt></ruby>だけでは動かない。<ruby>最後<rt>さいご</rt></ruby>は「<ruby>金<rt>かね</rt></ruby>がものをいう」のが現実だ。", exampleTrans: "現實世界不能只靠理想運轉。到了關鍵時刻往往「有錢能使鬼推磨」，這就是殘酷的現實。" },
  { id: 145, group: 15, kanji: "<ruby>金<rt>きん</rt></ruby>に<ruby>目<rt>め</rt></ruby>がくらむ", kanjiPlain: "金に目がくらむ", meaning: "利慾薰心；被金錢財富誘惑蒙蔽雙眼、失去正常理智道德。", story: "「くらむ（眩む）」為眼前發黑眩暈。面對巨額財富利益的致命誘惑，眼睛被晃得目眩神迷，從而喪失清醒的判斷力與良知道德。", example: "<ruby>金<rt>かね</rt></ruby>に<ruby>目<rt>め</rt></ruby>がくらんで、<ruby>犯罪<rt>はんざい</rt></ruby>に<ruby>手<rt>て</rt></ruby>を<ruby>染<rt>そ</rt></ruby>めてしまった。", exampleTrans: "因為利慾薰心、被金錢蒙蔽了心智，最終走上了鋌而走險的犯罪道路。" },
  { id: 146, group: 15, kanji: "<ruby>金<rt>きん</rt></ruby>の<ruby>切<rt>き</rt></ruby>れ<ruby>目<rt>め</rt></ruby>が<ruby>縁<rt>えん</rt></ruby>の<ruby>切<rt>き</rt></ruby>れ<ruby>目<rt>め</rt></ruby>", kanjiPlain: "金の切れ目が縁の切れ目", meaning: "錢盡緣分盡；建立在金錢利益上的虛假交情，一旦囊中羞澀關係便戛然而止。", story: "雙方的交誼若僅建立在金錢買賣或酒肉利益之上，一旦財富耗盡（金の切れ目），彼此的緣分與交情（縁）也會立即隨之徹底斷絕。諷刺市儈人情之冷酷。", example: "「<ruby>金<rt>かね</rt></ruby>の<ruby>切<rt>き</rt></ruby>れ<ruby>目<rt>め</rt></ruby>が<ruby>縁<rt>えん</rt></ruby>の<ruby>切<rt>き</rt></ruby>れ<ruby>目<rt>め</rt></ruby>」というように、破産したら取り巻きが潮を引くように去った。", exampleTrans: "正如俗話說錢盡緣分斷，破產之後那些圍繞身邊的酒肉朋友便如潮水般作鳥獸散。" },
  { id: 147, group: 15, kanji: "<ruby>金<rt>かね</rt></ruby><ruby>持<rt>も</rt></ruby>ち けんかせず", kanjiPlain: "金持ち けんかせず", meaning: "富人不行險、和氣生財；富有者深知衝突爭執只會招致損失，因此行事求和忍讓。", story: "家財萬貫的富人擁有眾多資產，如果與人爭鬥毆打，一旦受傷或惹上官司招致的損失遠大於一時爭強鬥勝的快感，故多採取退讓自保策略。", example: "「<ruby>金持<rt>かねも</rt></ruby>ちけんかせず」で、つまらない挑発には乗らないのが賢明だ。", exampleTrans: "正所謂「和氣生財、明哲保身」，面對無聊低級的挑釁不予理會才是最聰明的做法。" },
  { id: 148, group: 15, kanji: "かぶとをぬぐ", kanjiPlain: "かぶとをぬぐ", meaning: "甘拜下風、繳械認輸；承認自己的實力不如對方、由衷心服口服。", story: "「兜（かぶと）」指古代武士作戰時作戰時穿戴的堅硬頭盔。在戰場上摘下頭盔，代表放棄抵抗、俯首認輸。比喻在對手卓越的實力面前心服口服、甘拜下風。", example: "<ruby>彼<rt>かれ</rt></ruby>のあまりの<ruby>博識<rt>はくしき</rt></ruby>ぶりには、<ruby>専門家<rt>せんもんか</rt></ruby>もかぶとをぬぐしかなかった。", exampleTrans: "面對他淵博過人的驚人學識，就連專業權威學者也不得不甘拜下風、自嘆不如。" },
  { id: 149, group: 15, kanji: "<ruby>臥<rt>が</rt></ruby><ruby>薪<rt>しん</rt></ruby><ruby>嘗<rt>しょう</rt></ruby><ruby>胆<rt>たん</rt></ruby>", kanjiPlain: "臥薪嘗胆", meaning: "臥薪嘗膽；忍辱負重、刻苦自勵，為了報仇雪恥或達成大志歷經千辛萬苦。", story: "出自《史記·越王句踐世家》。吳王夫差睡在柴草上（臥薪）不忘父仇；越王句踐戰敗後親嘗苦膽（嘗膽）激勵鬥志。形容為了雪恥復興而甘受苦楚、堅忍不拔。", example: "<ruby>一度<rt>いちど</rt></ruby>の<ruby>敗北<rt>はいぼく</rt></ruby>をバネに、<ruby>臥薪嘗胆<rt>がしんしょうたん</rt></ruby>の<ruby>思<rt>おも</rt></ruby>いで<ruby>特訓<rt>とっくん</rt></ruby>に<ruby>励<rt>はげ</rt></ruby>んだ。", exampleTrans: "把上一次的失敗化為動力，以臥薪嘗膽的堅定意志埋首投入嚴苛的特訓。" },
  { id: 150, group: 15, kanji: "<ruby>合<rt>がっ</rt></ruby><ruby>点<rt>てん</rt></ruby>がいかない", kanjiPlain: "合点がいかない", meaning: "百思不得其解、難以理解認同；對事情的理由無法由衷接受或釋懷。", story: "「合点（がてん）」指理解、認可、點頭首肯。即使聽了各種理由藉口，心裡仍感到不對勁、無法說服自己同意。形容困惑、納悶或對處置方式無法信服。", example: "<ruby>彼<rt>かれ</rt></ruby>の<ruby>説明<rt>せつめい</rt></ruby>はどうにも<ruby>合点<rt>がてん</rt></ruby>がいかない。", exampleTrans: "他的這番解釋與說法，無論怎麼聽都讓人百思不得其解、難以信服。" }
];